L["Skyriding HUD with speed, vigor and second wind tracking."] = "驭空术HUD，包含速度、精力及第二风追踪。"
L["Customizing Unlock Mode: %s (changes apply only to this group's specs)"] = "自定义解锁模式：%s（更改仅适用于此组的专精）"
L["After anchoring, drag to an edge and choose a grow direction to maintain its corner spot as bars change size."] = "锚定后，拖动到边缘并选择增长方向，以便在条改变大小时保持其角落位置。"
