L["Window & Tooltip Skins"] = "窗口与提示框皮肤"
L["Full Export"] = "完整导出"
L["Export All Data with Profile"] = "随配置导出所有数据"
L["UI Scale Issue: Profile was made at %1$d%%, yours is %2$d%%"] = "UI缩放问题：配置文件的UI缩放为 %1$d%%，你的为 %2$d%%"
L["Name Font"] = "名称字体"
L["EUI Options Panel Scale"] = "EUI选项面板缩放"
L["System Default"] = "系统默认"
L["Promote Override to Profile"] = "将覆盖转换为配置文件"
L["Rescue tool for a profile built inside an override: the selected group's settings and layouts become this profile's own baseline, then ALL spec override groups are deleted. Conditional overrides are not affected."] = "针对在覆盖中创建的配置文件的恢复工具：选中组的设置和布局将成为该配置文件的新基础，随后所有专精覆盖组将被删除。条件覆盖保持不变。"
L["Promote Override & Delete ALL Overrides"] = "将覆盖转换为配置文件并删除所有覆盖"
L["Override to Promote"] = "待转换的覆盖"
L["Promote & Reload"] = "转换并重载"
L["This cannot be undone. Consider exporting this profile as a backup first."] = "此操作无法撤销。建议先导出当前配置文件作为备份。"
L["This export includes cross profile settings that will overwrite the importing user's settings including Quality of Life, Hovercast and more that should typically not be shared with standard profiles. THIS IS NOT RECOMMENDED for public sharing of profiles."] = "此导出包含跨配置的设置，将覆盖导入用户的设置，包括便捷功能、悬停施法等通常不应随标准配置共享的内容。不建议将此用于公开分享配置。"
L["This permanently overwrites this profile's settings with the override '%s': its captured settings and its custom Unlock Mode and Buff Manager layouts (where present) become the profile's own baseline for every spec. ALL spec override groups on this profile are then deleted and the UI reloads. Conditional overrides are not affected."] = "这将使用覆盖方案‘%s’永久覆盖当前配置文件的设置：其已捕获的设置以及自定义的解锁模式与增益管理器布局（如有）将成为该配置文件下所有专精的基准设置。随后，该配置文件中的所有专精覆盖组都将被删除并重新加载界面。条件覆盖不受影响。"
L["Type \"%s\" to enable:"] = "输入“%s”以启用："
L["Nothing Extra"] = "无额外"
L["Window Skins"] = "窗口皮肤"
L["No spec overrides yet. Click the spec glyph next to the module search bar, select or create a spec group, and any setting you change while editing as that group is saved here."] = "尚无专精覆盖。点击模块搜索栏旁的专精图标，选择或创建一个专精组，您在该组编辑模式下更改的任何设置都将保存在此处。"

L["Import the sharer's complete override setup: spec and conditional override values, groups, their custom Unlock Mode layouts, and Buff Manager overrides. This replaces ALL of your own overrides. Off = keep yours untouched."] = "导入分享者的完整覆盖设置：专精与条件覆盖值、分组、自定义解锁模式布局以及增益管理器覆盖。这将替换你自己的所有覆盖设置。关闭 = 保留你的设置不变。"
L["This profile string does not carry any override data."] = "此配置字符串不包含任何覆盖数据。"
L["This profile was made at %1$d%% UI scale; yours is %2$d%%. Change your UI scale to match the imported profile? This will show all profiles at this scale as UI Scale is not a per-profile setting, but can be changed at any time back to your original value."] = "此配置是在 %1$d%% UI 缩放比例下制作的；你的是 %2$d%%。是否更改 UI 缩放以匹配导入的配置？这会使所有配置都显示为此缩放比例，因为 UI 缩放不是按配置单独设置的，但你可以随时改回原始值。"
L["UI Scale Mismatch"] = "UI 缩放不匹配"
L["\"%1$s\" was saved but cannot be loaded because this spec has an assigned profile."] = "“%1$s”已保存，但由于此专精已分配配置，无法加载。"
L["ADDITIONAL FEATURES"] = "附加功能"
L["Apply the sharer's Blizz UI Enhanced Window Skins and Tooltips, Menus & Popups settings. These are account-wide and will overwrite yours across ALL profiles. Off = keep your own."] = "应用分享者的 Blizz UI 增强窗口皮肤和提示、菜单和弹窗设置。这些是战网通行证范围的，并将覆盖你所有配置中的设置。关闭 = 保留你自己的。"
L["Could not build the export string."] = "无法构建导出字符串。"
L["Export Failed"] = "导出失败"
L["Import & Reload"] = "导入并重新加载"
L["Import Full Account Data"] = "导入完整账号数据"
L["New Overrides System"] = "新覆盖系统"
L["Overwrite Window & Tooltip Settings?"] = "覆盖窗口和提示设置？"
L["Promoting an override reloads the UI and cannot run in combat. Leave combat and try again."] = "提升覆盖会重新加载界面，且不能在战斗中进行。离开战斗再试。"
L["Remove '%s'? The setting keeps its current live value."] = "移除“%s”？该设置将保留当前的生效值。"
L["Remove Stranded Override"] = "移除残留覆盖"
L["Remove the stranded '%s' override for %s? The spec returns to the shared default."] = "移除 %s 的残留覆盖“%s”？该专精将恢复到共享默认值。"
L["Stranded Overrides"] = "残留覆盖"
L["These specs hold override values that no group's editing mode can reach anymore (left behind by membership changes). They still apply. Remove one to return that spec to the shared default."] = "这些专精持有的覆盖值已无法被任何分组的编辑模式访问（因成员变更而遗留）。它们仍然生效。移除一个可使该专精恢复到共享默认值。"
L["This cannot be undone. Export your own profile as a backup first."] = "此操作无法撤销。请先导出你自己的配置作为备份。"
L["This profile string does not carry any Window & Tooltip Skins settings."] = "此配置字符串不包含任何窗口和提示皮肤设置。"
L["This string is a FULL ACCOUNT export. It replaces your account-wide settings with the sender's, including Quality of Life, HoverCast bindings, Cooldown Manager spell setups, unlock anchors, UI scale, and profile keybinds -- not just a profile. Your other profiles are kept, but a profile with the same name is replaced."] = "此字符串为完整账号导出。它会将发送者的战网通行证范围设置替换你的，包括便捷功能、HoverCast 绑定、冷却管理器法术设置、解锁锚点、UI 缩放和配置快捷键 —— 不仅仅是配置。你的其他配置会被保留，但同名的配置会被替换。"
L["This will replace YOUR Blizz UI Enhanced settings (the Window Skins and Tooltips, Menus & Popups tabs) with the sharer's, across ALL of your profiles. Your current settings on those two tabs cannot be recovered afterward."] = "这会将分享者的 Blizz UI 增强设置（窗口皮肤和提示、菜单和弹窗标签页）替换你的设置，覆盖你的所有配置。之后你在这两个标签页上的当前设置将无法恢复。"
L["|cffff6060[EllesmereUI]|r A profile named \"%1$s\" already exists."] = "|cffff6060[EllesmereUI]|r 名为“%1$s”的配置已存在。"
L["|cffff6060[EllesmereUI]|r Cannot rename to \"Default\"."] = "|cffff6060[EllesmereUI]|r 无法重命名为“默认”。"
L["This feature optimizes your in-game graphics settings to give you the best combination of high FPS and visual clarity.\n\nYou can revert all changes at any time by clicking \"Restore My Settings\" which will appear after optimizing.\n\n\nWhat we change:\n\n"] = "此功能优化你的游戏图形设置，以提供高 FPS 和视觉清晰度的最佳组合。\n\n你可以在优化后点击出现的“恢复我的设置”随时还原所有更改。\n\n\n我们会更改的内容：\n\n"
L["Overrides are locked: this page's custom Buff Manager is active. Leave the Buff Manager tab to manage overrides."] = "覆盖已锁定：此页面的自定义增益管理器已激活。离开增益管理器标签页以管理覆盖。"
L["The override group '%s' already provides the custom unlock mode for your current spec. Customize it there, or remove this spec from that group."] = "覆盖组 '%s' 已经为您的当前专精提供了自定义解锁模式。请在那里进行自定义，或从该组中移除此专精。"
L["Showing the '%s' override's value. Edit it from that override's editing mode."] = "显示 '%s' 覆盖的值。请从该覆盖的编辑模式中进行编辑。"
L["This spec's custom unlock mode is owned by '%s'. Customize it there, or remove the spec from that group."] = "此专精的自定义解锁模式由 '%s' 拥有。请在那里自定义，或从该组中移除此专精。"
L["Texture Not Found"] = "未找到纹理"
L["Fill the health bar bottom-to-top instead of left-to-right. Reverse Fill flips it to top-to-bottom."] = "将生命条从下往上填充而不是从左到右。反向填充则反过来（从上往下）。"
L["Video Guide: Cooldown Manager"] = "视频指南：冷却管理"
L["Changing the frame source requires a UI reload to take effect."] = "更改框体来源需要重载UI才能生效。"
L["Beacon Reminders"] = "信标提醒"
L["Clique controls click-casting on the same Raid Frames as EllesmereUI's HoverCast, so they conflict. Disable the Clique addon to use HoverCast."] = "Clique 与 EllesmereUI 的 HoverCast 在同一团队框体上控制点击施法，因此存在冲突。请禁用 Clique 插件以使用 HoverCast。"
L["Conditional"] = "条件"
L["On"] = "开启"
L["[ Import string captured (%1$s characters) ]"] = "[ 已捕获导入字符串（%1$s 个字符） ]"
L["no key set"] = "未设置按键"

-- 核心提示 (Core Tooltip)
L["*Blizzard's auto targeting (soft target) setting can cause brief flickering when your actual target dies but a soft-target is still active."] = "*暴雪的自动目标（软目标）设置在您实际目标死亡但软目标仍激活时可能导致短暂闪烁。"
L["|cff0cd29dLeft-click:|r |cffE0E0E0Toggle EllesmereUI|r"] = "|cff0cd29d左键单击：|r |cffE0E0E0切换 EllesmereUI|r"
L["|cff0cd29dMiddle-click:|r |cffE0E0E0Hide Minimap Button|r"] = "|cff0cd29d中键单击：|r |cffE0E0E0隐藏微缩地图按钮|r"
L["|cff0cd29dRight-click:|r |cffE0E0E0Enter Unlock Mode|r"] = "|cff0cd29d右键单击：|r |cffE0E0E0进入解锁模式|r"
L["Addon not loaded"] = "插件未加载"
L["Anchor to Cursor"] = "跟随鼠标"
L["Coming soon"] = "即将推出"
L["Controls the text rendering style used across all UI elements"] = "控制所有界面元素使用的文本渲染样式"
L["Disable "] = "禁用 "
L["Discord"] = "Discord"
L["Enable "] = "启用 "
L["Enables sharpening to improve image clarity. Especially noticeable at lower render scales."] = "启用锐化以提高图像清晰度。在较低渲染比例下尤其明显。"
L["Havoc"] = "浩劫"
L["Hides the EllesmereUI button from the game's Escape/pause menu."] = "从游戏 Esc/暂停菜单中隐藏 EllesmereUI 按钮。"
L["Hides the sync icons on the sidebar module list."] = "隐藏侧栏模块列表上的同步图标。"
L["Hides the Unlock Mode button from the game's Escape/pause menu. You can still toggle Unlock Mode from the EUI options panel."] = "从游戏 Esc/暂停菜单中隐藏解锁模式按钮。您仍然可以从 EUI 选项面板切换解锁模式。"
L["Import the anchor & size-match relationships from this profile. Off = keep your own layout; only the selected modules' own positions/settings come in."] = "从此配置导入锚定和大小匹配关系。关 = 保持您自己的布局；仅导入所选模块自身的位置/设置。"
L["In Maintenance"] = "维护中"
L["Include the anchor & size-match relationships between modules. Off = export each module's own positions only, with no cross-module tying."] = "包含模块之间的锚定和大小匹配关系。关 = 仅导出每个模块自身的位置，无跨模块绑定。"
L["Keybinds respond on key down instead of key up. This helps make your abilities feel more responsive."] = "快捷键在按下键时响应，而非松开时。这有助于让您的技能感觉更灵敏。"
L["No other profiles to sync to"] = "没有其他配置可同步"
L["No Profile Level Customizations"] = "无配置级别自定义"
L["Optimizes your graphics settings for maximum FPS and visual clarity."] = "优化您的图形设置以获得最大 FPS 和视觉清晰度。"
L["Patreon"] = "Patreon"
L["PayPal"] = "PayPal"
L["Pet Move"] = "宠物移动"
L["Prevents Blizzard from dimming Swiftmend on action bars and CDM based on Efflorescence state."] = "防止暴雪根据百花齐放状态使动作条和 CDM 上的迅愈变暗。"
L["Reset to default"] = "重置为默认"
L["Set UI Scale to 0.5333"] = "将UI缩放设为 0.5333"
L["Sets the accent color used across all EllesmereUI elements (tabs, glows, highlights, borders). Defaults to your theme color."] = "设置所有 EllesmereUI 元素（标签、发光、高亮、边框）使用的强调色。默认为您的主题颜色。"
L["Sets the scale of the entire game UI. Lower values make everything smaller, higher values make everything larger."] = "设置整个游戏界面的缩放。较低的值会使所有内容变小，较高的值会使所有内容变大。"
L["Sets the UI scale to the exact pixel-perfect value used by other addons. EllesmereUI does not require this to be pixel perfect."] = "将UI缩放设置为其他插件使用的精确像素完美值。EllesmereUI 不要求此值像素完美。"
L["Show Combat Damage Text"] = "显示战斗伤害文本"
L["The display language for the EllesmereUI options panel. Auto follows your game client. Untranslated text falls back to English."] = "EllesmereUI 选项面板的显示语言。自动跟随您的游戏客户端。未翻译的文本将回退为英文。"
L["This bar will only show if you have an enemy targeted"] = "此条仅在您有敌方目标时显示"
L["This element doesn't support both Height and Width matching"] = "此元素不支持同时匹配高度和宽度"
L["This feature requires Snap Elements to be enabled"] = "此功能需要启用吸附元素"
L["This is the Spell Queue Window, it helps with making sure you can't queue up too many spells at once which makes the game feel laggy. Recommended settings are generally a minimum of 200 + your local ping. If you are unsure of exactly what this setting does, leave it at 400."] = "这是法术队列窗口，有助于确保您不会同时排队过多法术，以免游戏感觉卡顿。推荐设置通常至少为 200 + 您的本地延迟。如果您不确定此设置的确切作用，请保持 400。"
L["This option is only available for the Custom Color Theme"] = "此选项仅适用于自定义颜色主题"
L["Toggle EllesmereUI's optional buttons: the Escape menu buttons and the minimap button."] = "切换 EllesmereUI 的可选按钮：Esc 菜单按钮和微缩地图按钮。"
L["Twitch"] = "Twitch"
L["WARNING: This feature requires you to re-log or restart WoW to take effect."] = "警告：此功能需要您重新登录或重启魔兽世界才能生效。"
L["Your current spec has an assigned profile so you cannot switch to another. Please unassign to switch."] = "您当前的专精已分配配置，因此无法切换到另一个。请取消分配以切换。"
L["Turns Dark Mode on or off for the class resource bar."] = "开启或关闭职业资源条的深色模式。"
L["Turns Dark Mode on or off for Unit Frames and Raid Frames at once."] = "同时开启或关闭单位框体和团队框体的深色模式。"
L["Video Guide: Unlock Mode"] = "视频指南：解锁模式"
L["Shift + right click to hide video guide icons"] = "Shift + 右键点击以隐藏视频指南图标"
L["Show one-time video guide badges next to new or complex features. Each badge disappears forever once clicked."] = "在新功能或复杂功能旁显示一次性的视频指南徽章。每个徽章点击后永久消失。"
L["Blackens power-colored Power Bar backgrounds (Unit Frames and Raid Frames) by this amount, on top of Power Color Darken."] = "在能量颜色暗化的基础上，将能量条背景（单位框体和团队框体）按此数值加深。"
L["This module can't be overridden. Exit the override editing session to open it."] = "此模块无法被覆盖。请退出覆盖编辑会话以打开它。"
L["This can't change which spells the user tracks in Blizzard's CDM.\nIt's recommended to also share your Blizzard CDM layout for any spec you choose here."] = "这不会改变用户在暴雪CDM中追踪的法术。\n建议也为你在此选择的任何专精共享你的暴雪CDM布局。"
L["Elements cannot be anchored to\n"] = "元素无法锚定到\n"
L["Always show less common settings instead of collapsing them behind a Show Less Common link."] = "始终显示不常用设置，而不是将其折叠起来，仅通过“显示不常用设置”链接展开。"
L["Include your complete override setup: spec and conditional override values, groups, their custom Unlock Mode layouts, and Buff Manager overrides. On import this replaces the recipient's overrides entirely."] = "包含你的完整覆盖设置：专精和条件覆盖值、组、它们的自定义解锁模式布局以及增益管理器覆盖。导入时，这将完全替换接收者的覆盖。"
L["Include fonts, custom colours, dark mode, accent colour and UI scale with this export. Off = only the selected modules' own settings export, keeping the recipient's global look."] = "在导出中包括字体、自定义颜色、暗色模式、强调色和UI缩放。关闭则仅导出所选模块自身的设置，保留接收者的全局外观。"
L["Include your Blizz UI Enhanced settings from the Window Skins and Tooltips, Menus & Popups tabs. These are account-wide: if the importer opts in, they overwrite that player's settings across ALL of their profiles."] = "包含来自窗口皮肤和提示框、菜单与弹出窗口标签页的暴雪界面增强设置。这些设置为账号通用：如果导入者选择启用，它们将覆盖该玩家所有配置中的相应设置。"
L["Sets the font for the names that float above players, NPCs and enemies in the world.\n\nSeparate from Global Font - changing this does not affect the rest of the UI, and Global Font does not affect it.\n\nBlizzard Default leaves the name text completely untouched.\n\n|cffff4d4dRequires a re-log or restart of WoW to take effect.|r"] = "设置游戏中玩家、NPC和敌人头顶浮动名称的字体。\n\n独立于全局字体——更改此设置不会影响界面其余部分的字体，全局字体也不会影响它。\n\n选择“暴雪默认”将完全保留名称文本的原样。\n\n|cffff4d4d需要重新登录或重启魔兽世界才能生效。|r"

-- 核心弹窗 (Core Popup)
L["Are you sure you want to reset ALL EUI addon settings to their defaults? This will reload your UI."] = "您确定要将所有 EUI 插件设置重置为默认值吗？这将重载您的界面。"
L["Better Character Panel conflicts with the EllesmereUI's Character Sheet. Disable either Better Character Panel or the Character Sheet skin in Blizzard UI Enhanced settings."] = "Better Character Panel 与 EllesmereUI 的角色面板冲突。请在暴雪界面增强设置中禁用 Better Character Panel 或角色面板皮肤。"
L["Blizzard's Edit Mode snapping may not work correctly until you reload your UI."] = "暴雪编辑模式的吸附功能在您重载界面之前可能无法正常工作。"
L["Changing cursor anchor requires a UI reload to take effect."] = "更改光标锚点需要重载界面才能生效。"
L["Changing the language requires a UI reload."] = "更改语言需要重载界面。"
L["Chonky Character Sheet conflicts with the EllesmereUI's Character Sheet. Disable either Chonky or the Character Sheet skin in Blizzard UI Enhanced settings."] = "Chonky Character Sheet 与 EllesmereUI 的角色面板冲突。请在暴雪界面增强设置中禁用 Chonky 或角色面板皮肤。"
L["Combat text font changes require a logout to character select to take effect. This is a WoW engine limitation."] = "战斗文本字体更改需要登出到角色选择界面才能生效。这是魔兽世界引擎的限制。"
L["Deja Character Stats conflicts with the EllesmereUI's Character Sheet. Disable either Deja or the Character Sheet skin in Blizzard UI Enhanced settings."] = "Deja Character Stats 与 EllesmereUI 的角色面板冲突。请在暴雪界面增强设置中禁用 Deja 或角色面板皮肤。"
L["Enable & Reload"] = "启用并重载"
L["Enter a name for the new profile:"] = "为新配置输入名称："
L["Leatrix Plus has chat and minimap features that conflict with EllesmereUI. Disable any chat or minimap related options within Leatrix Plus to stay compatible."] = "Leatrix Plus 的聊天和微缩地图功能与 EllesmereUI 冲突。请禁用 Leatrix Plus 中任何与聊天或微缩地图相关的选项以保持兼容。"
L["Many of ElvUI's modules are incompatible with EllesmereUI. Make sure to disable any conflicting modules."] = "ElvUI 的许多模块与 EllesmereUI 不兼容。请确保禁用任何冲突的模块。"
L["Reset All & Reload"] = "重置全部并重载"
L["Save & Exit"] = "保存并退出"
L["TellMeWhen overlaps with EllesmereUI's core positional architecture. If you ONLY use for sound alerts it should be okay but may still cause issues."] = "TellMeWhen 与 EllesmereUI 的核心位置架构重叠。如果您仅用于声音警报，可能还好，但仍可能引起问题。"
L["UI scale set to 0.5333. A reload is recommended."] = "UI缩放已设为 0.5333。建议重载。"
L["You have unsaved position changes.\nWhat would you like to do?"] = "您有未保存的位置更改。\n您想怎么做？"
L["%1$s Module"] = "%1$s 模块"
L["A profile named \"%1$s\" already exists. Please choose a different name."] = "名为 \"%1$s\" 的配置已存在。请选择其他名称。"
L["Anchor to %1$s"] = "锚定到 %1$s"
L["Are you sure you want to %1$s %2$s?"] = "您确定要 %1$s %2$s 吗？"
L["Are you sure you want to reset all %1$s settings to their defaults? This will reload your UI."] = "您确定要将所有 %1$s 设置重置为默认值吗？这将重载您的界面。"
L["Are you sure you want to reset all %s settings to their defaults? This will reload your UI."] = "您确定要将所有 %s 设置重置为默认值吗？这将重载您的界面。"
L["Elements cannot be anchored to\n%s"] = "元素无法锚定到\n%s"
L["Export will include %1$s of %2$s addons."] = "导出将包含 %2$s 个插件中的 %1$s 个。"
L["Import will include %1$s of %2$s addons."] = "导入将包含 %2$s 个插件中的 %1$s 个。"
L["Importing %1$s"] = "正在导入 %1$s"
L["Keybind: %1$s"] = "快捷键：%1$s"
L["Linked by Anchor/Width/Height Matching to: %s. These export together."] = "通过锚点/宽度/高度匹配链接到：%s。这些会一起导出。"
L["Linked by Anchor/Width/Height Matching to: %s. These import together."] = "通过锚点/宽度/高度匹配链接到：%s。这些会一起导入。"
L["Resolution Issue: Profile was made at %dx%d, yours is %dx%d"] = "分辨率问题：配置创建于 %dx%d，您的为 %dx%d"
L["Select which specs you want %s to be assigned to"] = "选择要将 %s 分配到的专精"
