L["Snap to: %1$s"] = "吸附到：%1$s"
L["Include CDM Spell Layout?"] = "包含冷却管理器法术布局？"
L["Include your Cooldown Manager spell layout (which spells sit on which bars) plus all per-spell settings for any specs you choose."] = "包含你的冷却管理器法术布局（即哪些法术位于哪些条上）以及你所选任何专精的每个法术的所有设置。"
