L["No"] = "否"
L["Use arrow keys to move selected element 1px any direction"] = "使用方向键将所选元素向任意方向移动1像素"
L["Shift+Right Click to temporarily hide overlay"] = "Shift+右键单击可暂时隐藏覆盖层。"
L["Group Death Alert"] = "队伍死亡提醒"
L["Group Loot"] = "队伍拾取"
L["The Cooldown Manager can do far more than show cooldowns, it also has per-spell settings, bar glows, tracking bars and more! Check out some tips and tricks for getting more from it."] = "冷却管理器能做的远不止显示冷却，它还拥有每个法术的设置、条发光、追踪条等更多功能！查看一些提示与技巧以从中获得更多。"
L["Show a pulsing dot on the Patch Notes button whenever EllesmereUI updates to a new version."] = "当EllesmereUI有版本更新时，在补丁说明按钮上显示脉动指示点。"

