L["Show combat indicator preview"] = "显示战斗指示器预览"
L["Show the name of who the boss is casting on."] = "显示首领正在施法的目标名称。"
L["Shows the raid target marker icon on boss frames."] = "在首领框体上显示团队目标标记图标。"
