L["Show dispel overlay preview"] = "显示驱散覆盖层预览"
L["Show one decimal place on health text: health values like 240.5k and health percent like 77.3%. Power text is unaffected. Off by default."] = "在生命值文本上显示一位小数，例如生命值显示为240.5k，生命百分比显示为77.3%。能量值文本不受影响。默认关闭。"
L["Fades boss frames when the boss is out of range of your spells. Set to 100% to disable the fade."] = "当首领超出你的法术范围时，淡出首领框体。设置为100%可禁用淡出效果。"
L["Show the main frames' hover highlight border on this frame. Turn off so this frame never recolors on mouseover. No effect when Highlight is off in the main frames' Hover Borders."] = "在这个框体上显示主框体的悬停高亮边框。关闭后，该框体在鼠标悬停时永不重新着色。当主框体的“鼠标指向边框”中的“高亮”关闭时，此设置无效果。"
L["Overrides the Frame Strata set in the main frames for this frame only. Controls the order that overlapping frames display in; set higher to show above other frames."] = "仅为此框体覆盖主框体中设置的框体层级。控制重叠框体的显示顺序；设置更高以显示在其他框体之上。"
L["Overrides the border size from the main frames for this frame only. Border color and texture still follow the main frames."] = "仅为此框体覆盖主框体的边框大小。边框颜色和纹理仍遵循主框体。"
L["Show player nicknames from supported addons instead of character names on your main frames."] = "在主框体上显示来自受支持插件的玩家昵称，而非角色名称。"
L["Force boss buffs into a single large column matched to the frame height."] = "将首领增益强制放入与框体高度匹配的单个大列中。"
L["Force boss debuffs into a single large column matched to the frame height."] = "将首领减益强制放入与框体高度匹配的单个大列中。"
L["Show Duration (Inside Cog)"] = "显示持续时间（齿轮内）"
L["Custom Background Color"] = "自定义背景颜色"
L["Class Colored Background"] = "职业着色背景"
L["Sets a custom width for the cast bar. Set to 0 to match the boss frame width."] = "为施法条设置自定义宽度。设为0以匹配首领框体宽度。"
L["Render absorbs on Boss Frames using the Target frame's absorb styling."] = "使用目标框体的吸收样式在首领框体上显示吸收盾。"
L["Hide dispel overlay preview"] = "隐藏驱散覆盖层预览"
L["Fades the entire frame (portrait, health and power bars, text) while out of combat."] = "脱离战斗时淡出整个框体（头像、生命条和能量条、文本）。"
L["Enable Fade Out of Combat first"] = "脱离战斗淡出"
L["Only applies when Name or Name > Target is selected."] = "“名称”或“名称 > 目标”"
L["Only applies when Name > Target is selected."] = "“名称 > 目标”"
L["Shows the overlay only for debuffs you can currently dispel."] = "仅对你可以驱散的减益效果显示覆盖层。"
L["Not available for this combat indicator style."] = "不适用于此战斗指示器样式。"
L["Choose which tooltips appear on hover. Affects all unit frames, including boss frames."] = "选择悬停时显示哪些提示框。影响所有单位框体，包括首领框体。"
L["Buffs join the debuff stack as its first rows; debuffs continue on the next row and move as buff rows change."] = "增益作为减益堆叠中的首行加入；减益位于下一行，并随增益行数的变化而移动。"
L["Power Colored Fill. Power colors can be adjusted in Global Settings -> Fonts & Colors."] = "能量着色填充。能量颜色可在全局设置 -> 字体和颜色中调整。"
L["Apply Extra Text to all Frames"] = "将额外文本应用于所有框体"
L["Adds a Shadow border to your player frame when you pull or hold threat as a non-tank. Only active in dungeons, raids and delves."] = "当你作为非坦克角色产生或保持仇恨时，为你的玩家框体添加阴影边框。仅在地城、团队副本和探索中生效。"
L["Appends the cast target to the spell name (Spell Name - Target), class colored, and disables the separate Spell Target display."] = "将施法目标附加到法术名称后（法术名称 - 目标），按职业着色，并禁用独立的法术目标显示。"
L["Apply Absorb Style, color and rendering to all Frames"] = "将吸收样式、颜色和渲染应用于所有框体"
L["Apply All Settings"] = "应用所有设置"
L["Bar Background Color"] = "条背景颜色"
L["Only show the cast bar while a cast is in progress; hide it the rest of the time."] = "仅在施法进行时显示施法条；其余时间隐藏。"
L["Opacity of the cast bar fill; below 100 the world shows through the fill instead of the background."] = "施法条填充的不透明度；低于 100 时，世界会透过填充显示，而不是背景。"
L["Lifts player, target, focus, and boss cast bars above other frames so they are never hidden behind them."] = "将玩家、目标、焦点和首领施法条提升到其他框体之上，使其永远不会被遮挡。"
L["Shows a small white tick mark where the cast will be when your interrupt comes off cooldown."] = "在打断技能冷却完成时，施法条上显示一个白色小刻度标记。"
L["Colors the cast segment during which your interrupt will be available."] = "为你的打断技能可用时的施法段着色。"
L["Place the cast icon on the right side of the bar instead of the left."] = "将施法图标放在条的右侧，而不是左侧。"
L["the Frame Source to be EllesmereUI"] = "框体来源为 EllesmereUI"
L["This frame's source changes require a UI reload to take effect."] = "此框体的来源更改需要重新加载界面才能生效。"
L["This option requires Combine Spell Name and Target to be disabled."] = "此选项需要禁用“合并法术名称与目标”。"
L["This overwrites the chosen frame's current settings. Frame position, visibility, and enable state are not changed."] = "这会覆盖所选框体的当前设置。框体位置、可见性和启用状态不会更改。"
L["Close to Aggro"] = "即将获得仇恨"
L["Show the unit's tooltip when hovering the frame itself."] = "悬停框体本身时显示单位提示框。"
L["Show aura tooltips when hovering buff and debuff icons on all unit frames except boss frames."] = "悬停除首领框体外的所有单位框体上的增益和减益图标时显示光环提示框。"
L["Show aura tooltips when hovering buff and debuff icons on boss frames."] = "悬停首领框体上的增益和减益图标时显示光环提示框。"
L["Show the pet frame whenever you have a pet, ignoring the Player frame's visibility settings."] = "无论何时拥有宠物时都显示宠物框体，忽略玩家框体的可见性设置。"

