L["No conditional overrides yet. Click the Conditional Overrides button next to the module search bar and create a conditional group (Dungeon, Raid, Keybind...). Spec overrides always take precedence over conditionals."] = "尚无条件覆盖。点击模块搜索栏旁边的“条件覆盖”按钮创建一个条件组（地下城、团队副本、快捷键...）。专精覆盖始终优先于条件覆盖。"
