L["Settings Overrides are the most powerful system in EllesmereUI, and the deepest. A few minutes with this video will save you hours of working it out on your own."] = "设置覆盖是EllesmereUI中最强大、也是最深入的系统。花几分钟观看此视频，将为你节省数小时自行摸索的时间。"
