L["Unlock Mode is how you move and resize everything in EllesmereUI, and it is packed with tools: anchors, width matching, fallback anchors, per-group layouts. This video gets you fluent fast."] = "解锁模式是您在EllesmereUI中移动和调整所有内容的方式，它配备了丰富的工具：锚点、宽度匹配、后备锚点、每组布局。此视频可助您快速上手。"
