--数据条鼠标提示（tooltip)
L["Horizontal bars lay blocks left to right; vertical bars stack them top to bottom."] = "水平条将模块从左到右排列；垂直条从上到下堆叠。"
L["EllesmereUI matches the window-skin shell; Modern is a flat color."] = "EllesmereUI 匹配窗口皮肤外壳；现代风格为纯色。"
L["Scales every text element on this bar."] = "缩放此条上的所有文本元素。"
L["Shows a faint white wash over each block on mouseover."] = "鼠标悬停时在每个模块上显示淡淡的白色覆盖。"
L["Opacity of the bar's background; the swatch picks the Modern color."] = "条背景的不透明度；色板用于选择现代风格颜色。"
L["Sizes the bar to the full screen extent along its axis."] = "将条沿其轴扩展到全屏。"
L["Pins the bar flush against a screen edge; moving the bar in unlock mode sets this back to None."] = "将条固定在屏幕边缘；在解锁模式下移动条会将其重置为“无”。"
L["Size of the bar along its block axis in pixels."] = "条沿模块轴的大小（像素）。"
L["Size of the bar across its block axis in pixels."] = "条跨模块轴的大小（像素）。"
L["Where the block's content sits inside its slot."] = "模块内容在槽位内的位置。"
L["Scales this block's content as a group inside its slot."] = "将此模块的内容作为一个整体在槽位内缩放。"
L["Tints this block's slot with its own color."] = "用其自身颜色为模块槽位着色。"
L["Stretches this block to absorb the space the sized blocks leave over; exactly one block per bar fills."] = "拉伸此模块以吸收其他已设定大小模块留下的空间；每个条恰好有一个填充模块。"
L["This block is already the 'Fill Remaining Space' block. Check another block to move the role."] = "此模块已是“填充剩余空间”模块。勾选其他模块以转移此角色。"
L["Pins this block's content to the exact center of the bar; blocks before it pack left, blocks after pack right. Combined with Fill Remaining, the block also absorbs the leftover space around the center."] = "将此模块的内容固定在条的正中央；前面的模块向左靠拢，后面的向右靠拢。与“填充剩余”结合时，该模块也会吸收中心周围的空间。"
L["Shows the online friend and guild counters."] = "显示在线好友和公会计数。"
L["Empty space reserved on this side of the block's content."] = "模块内容此侧保留的空白间距。"
L["Pick any currency your character has discovered."] = "选择你角色已发现的一种货币。"
L["Shows the currency icon next to the amount."] = "在金额旁显示货币图标。"
L["Automatic shows XP while leveling and reputation at max level."] = "自动模式在升级时显示经验，满级时显示声望。"
L["Renders the spec text in uppercase."] = "将专精文本显示为大写。"
L["Gap between the main menu button and the icon row."] = "主菜单按钮与图标行之间的间距。"
L["Gap between the micro menu icons."] = "微菜单图标之间的间距。"
L["Which micro menu buttons this block shows."] = "此模块显示哪些微菜单按钮。"
L["Shows an envelope icon when you have unread mail."] = "有未读邮件时显示信封图标。"
L["Shows a rest icon while your character is resting."] = "角色休息时显示休息图标。"
L["Local computer time instead of server time."] = "使用本地计算机时间而非服务器时间。"
L["Use 24-hour time."] = "使用24小时制。"
L["Shows the icon next to the durability readout."] = "在耐久度数值旁显示图标。"
L["Shows the coin icon next to the amount."] = "在金额旁显示硬币图标。"
L["Shows your free bag slots."] = "显示你的空背包格数。"
L["Shows silver and copper, not just gold."] = "显示银币和铜币，而不仅是金币。"
L["Where the icon strip sits inside its slot."] = "图标条在槽位内的对齐方式。"
L["Which audio channel the block's volume bar adjusts."] = "该模块的音量条所调节的音频通道。"
L["Uses Blizzard's coin textures instead of the letter suffixes."] = "使用暴雪的金币纹理代替字母后缀。"
L["Removes the block from the bar in instanced content, where player coordinates are unavailable."] = "在副本内容中从条上移除该模块，因为其中无法获取玩家坐标。"
L["Shows the zone and the subzone together instead of the subzone alone."] = "同时显示区域和子区域，而非仅显示子区域。"
L["How precise the coordinates read. More decimals make the block wider."] = "坐标读取的精确程度。更多小数位数会使模块更宽。"
L["Automatic follows the zone name. Manual holds the block at a fixed width and clips longer names, so it never shifts the blocks beside it."] = "自动模式跟随区域名称变化。手动模式将模块保持固定宽度并裁剪较长的名称，从而不会移动旁边的模块。"
L["Shows the map pin next to the zone name."] = "在区域名称旁显示地图标记。"
L["Which latency to show: home, world, or both side by side."] = "显示哪种延迟：本地、世界，或两者并排显示。"
L["Shows a house or globe icon marking which latency each value is."] = "显示房屋或地球图标，标识每个数值对应的延迟类型。"
L["Manual width is required."] = "手动宽度。"
L["How wide the block stays, whatever the zone is called."] = "无论区域名称如何变化，模块保持固定宽度。"
L["Shows the profession icons next to the text."] = "在文本旁显示专业图标。"
L["Shows the spec icon next to the text."] = "在文本旁显示专精图标。"
L["Shows the marker icon next to the coordinates."] = "在坐标旁显示标记图标。"
L["Background texture for this bar, tinted by the bar's color and opacity."] = "此条的背景纹理，由条的颜色和不透明度着色。"

