-- 光环与减益 (Auras & Debuffs)
L["Unlimited"] = "无限制"
L["Only show debuffs whose full duration is at most this many seconds. Combines with the filters; Unlimited applies no cap."] = "仅显示总持续时间不超过此秒数的减益。与过滤器合并生效；“无限制”则不设上限。"
L["Enter the maximum debuff duration in seconds:"] = "输入最大减益持续时间（秒）："

-- 框体可见性与专精覆盖 (Visibility & Overrides)
L["Not Skyriding (Airborne)"] = "非驭空术（空中）"
L["The exact inverse of Skyriding (Airborne): anything that is not airborne on a glide-capable mount or flight form, standing on the ground included."] = "与“驭空术（空中）”完全相反：任何未处于可滑翔坐骑或飞行形态空中状态的情形，包括站在地面上。"
L["In Vehicle"] = "载具中"
L["While seated in a vehicle."] = "乘坐载具时。"
L["Resting"] = "休息中"
L["While resting, in a city or at an inn."] = "处于休息状态时，在主城或旅店中。"
L["This element shows as soon as ONE Show condition matches. Hide keeps its meaning in both match modes: a checked Hide always hides, on every row."] = "只要满足任意一项“显示”条件，此元素就会显示。“隐藏”在两种匹配模式下的含义保持不变：勾选的“隐藏”在每一行都始终生效。"
L["Combines with the conditions below: shows outright once at least one passes, otherwise still reveals on hover. A checked Hide state still hides it, hover included."] = "与下方条件合并判断：只要满足至少一项条件即直接显示，否则仍可在鼠标悬停时显现。勾选的“隐藏”状态仍会将其隐藏，包括鼠标悬停。"
L["Makes this the override. It replaces the whole Visibility setting, so the conditions below no longer apply while it does. Click it again to remove the override."] = "将其设为覆盖。它会替换整个可见性设置，因此生效时下方的条件不再起作用。再次点击可移除该覆盖。"
L["Not overridable"] = "不可覆盖"
L["Not overridable. These conditions are shared and can only be changed while no override is being edited. An override replaces the Visibility setting outright -- Never, Always or Mouseover -- and ignores everything set here while it applies."] = "不可覆盖。这些条件是全局共享的，只有在未编辑任何覆盖时才能更改。覆盖会彻底替换可见性设置——从不、总是或鼠标悬停——并在生效时忽略此处设置的一切条件。"

