L["Color the health bar by how much health is left, instead of a flat color. Classic runs green at full health through yellow to red at empty. Custom Colors blends between the three stop swatches on this row -- full (100%), half (50%) and empty (0%). Class Reactive shows the class color at full health, bleeding into the 50% and 0% colors as the unit takes damage. Off leaves the flat Fill Color swatches in charge; either way the Gradient below still applies, running from whichever color this picks."] = "根据剩余生命值为生命条着色，而不是使用纯色。经典模式从满血的绿色经过黄色到空血的红色。自定义颜色在此行的三个色标之间混合——满（100%）、半（50%）和空（0%）。职业反应在满血时显示职业颜色，随着单位受到伤害渐变为 50% 和 0% 颜色。关闭时由纯填充颜色色标控制；无论哪种方式，下方的渐变仍然适用，从所选的任何颜色开始。"
