L["A group member to use as the tank. Empty uses the raid Main Tank, then the Dungeon Finder tank role. Updates out of combat."] = "用作坦克的队伍成员。留空则使用团队主坦克，其次是地下城查找器中的坦克职责。在脱离战斗时更新。"
