L["Hide Until Usable: only shown while usable and off cooldown, such as Overpower or Victory Rush after a proc; low resources do not hide it. Hide Outside Form/Stance: only shown in the form or stance the spell needs, even on cooldown. Keep Place leaves the gap; the others close it."] = "可用前隐藏：仅在可用且未冷却时显示，例如触发后的压制或乘胜追击；资源不足不会使其隐藏。形态/姿态外隐藏：仅在法术所需的形态或姿态中显示，冷却中也显示。保留位置会留下空隙；其他选项会收拢空隙。"
