L["Shift + Click World Markers"] = "Shift + 点击世界标记"
L["Shift + Left Click a marker icon to use its world marker item, then click the ground. Only markers whose item is in your bags get it; the rest keep Shift + Click to clear the target marker. Shift + Left Click the clear icon presses the server's Reset Markers button."] = "Shift + 左键点击标记图标以使用其世界标记物品，然后点击地面。只有物品在背包中的标记才有此功能；其余标记保持 Shift + 点击清除目标标记。Shift + 左键点击清除图标会按下服务器的重置标记按钮。"
L["Show a small coin in the corner of items marked as junk."] = "在标记为垃圾的物品角落显示一枚小硬币。"
L["Show at Max Level"] = "满级时显示"
L["Show Coin on Junk"] = "在垃圾上显示硬币"
L["Show Convert to Raid"] = "显示转化为团队"
L["Show Dividers"] = "显示分隔线"
L["Show Equipped Item Color"] = "显示已装备物品颜色"
L["Show Inspect Enchant Names Instead of Icons"] = "观察时显示附魔名称而非图标"
L["Show Item Icon Name"] = "显示物品图标名称"
L["Show Item ID on Tooltip"] = "在鼠标提示中显示物品 ID"
L["Show Player Buffs"] = "显示玩家增益"
L["Show Reinvite"] = "显示重新邀请"
L["Show Rested XP"] = "显示休息经验"
L["Show Target Name"] = "显示目标名称"
L["Show the coin button in the bag header. Click it, then click items to mark or unmark them as junk. Junk goes into its own Junk category, and a Sell Junk button appears next to the coin while a merchant is open."] = "在背包标题栏显示硬币按钮。点击它，然后点击物品以标记或取消标记为垃圾。垃圾会进入单独的垃圾类别，并在商人窗口打开时于硬币旁出现出售垃圾按钮。"
L["Shown at max level. Profession bonuses are only checked on your own sheet."] = "满级时显示。专业加成仅在你自己的角色面板上检查。"
L["Shows the common raid debuffs from anyone: armor, spell and physical damage taken, crit taken, attack power, attack and cast speed, healing taken, Judgements and Hunter's Mark."] = "显示任何人施加的常见团队减益：护甲、受到的法术和物理伤害、受到的暴击、攻击强度、攻击和施法速度、受到的治疗、审判和猎人印记。"
L["Shows the Convert to Raid button. In a raid of five or fewer it reads Convert to Party: everyone is removed and invited back to a new party."] = "显示转化为团队按钮。在五人或更少的团队中显示为转化为小队：所有人会被移出，并重新邀请进新的小队。"
L["Shows the debuffs you apply plus the common raid debuffs from anyone."] = "显示你施加的减益以及任何人施加的常见团队减益。"
L["Shows the Disband button. It always asks before disbanding, but hiding it puts it out of misclick range for good."] = "显示解散按钮。解散前总会先询问，但隐藏它可彻底避免误点。"
L["Shows the hovered player's buffs as icons next to the tooltip (up to 16)."] = "在鼠标提示旁以图标显示悬停玩家的增益（最多 16 个）。"
L["Shows the overlay, type icon and border colors only for debuffs you can currently dispel."] = "仅对你当前可驱散的减益显示覆盖层、类型图标和边框颜色。"
L["Shows the Reinvite button. It asks first, then removes everyone and invites them back to the same kind of group. Players have to accept the new invite."] = "显示重新邀请按钮。它会先询问，然后移出所有人并重新邀请进同类型的队伍。玩家需要接受新的邀请。"
L["Shows your damage taken, healing, avoids and combat enter/leave above the player frame instead of Blizzard's combat text, whose other messages are hidden while this is on. Move it in Unlock Mode."] = "在玩家框体上方显示你受到的伤害、治疗、闪避以及进入/离开战斗，取代暴雪的战斗文本；开启时暴雪战斗文本的其他消息会被隐藏。可在解锁模式中移动。"
L["Smart Ticks"] = "智能刻度"
L["Spell IDs in the Breakdown"] = "明细中的法术 ID"
L["Stagger Hits"] = "错开命中"
L["Stat Hover Highlight"] = "属性悬停高亮"
L["Static"] = "静态"
L["Straight"] = "直线"
L["Style Page Look Menus"] = "样式页面外观菜单"
L["Swipe Color"] = "冷却动画颜色"
L["Swipe Style"] = "冷却动画样式"
L["Tank Name"] = "坦克名称"
L["Text Shadow"] = "文字阴影"
L["The [Merfin] Experience Bar (Luxthos) WeakAura: blue to purple gradient, Quest XP Overlay, spark, rested after quest XP and seven texts with level, times and time to level."] = "[Merfin] Experience Bar (Luxthos) WeakAura：蓝到紫的渐变、任务经验叠加、火花、任务经验后的休息经验，以及包含等级、时间和升级所需时间的七段文本。"
L["The classic tooltip box around the meter window, with vanilla header buttons and every EllesmereUI meter feature."] = "计量窗口周围的经典鼠标提示边框，带有原版标题按钮及 EllesmereUI 计量器的全部功能。"
L["The gap between a nested menu's icons and the entry that opens it."] = "嵌套菜单的图标与打开它的条目之间的间距。"
L["The rested segment starts where the Quest XP Overlay ends instead of at your current XP."] = "休息经验段从任务经验叠加结束处开始，而不是从你的当前经验开始。"
L["The talent group this action menu works in. Outside it the keybind does nothing and the menu is hidden where it is nested."] = "此动作菜单生效的天赋组。在此之外快捷键无效，并且菜单在其嵌套位置隐藏。"
L["Third Timer"] = "第三个计时"
L["This option requires an EllesmereUI Focus frame."] = "此选项需要 EllesmereUI 焦点框体。"
L["This option requires XP Bar Style EllesmereUI or Luxthos"] = "此选项需要经验条样式为 EllesmereUI 或 Luxthos"
L["Time This Session and XP per Hour carry on through a /reload (a load within five minutes) instead of starting over."] = "本次会话时间和每小时经验在 /reload（五分钟内的载入）后继续累计，而不是重新开始。"
L["Timed Buffs"] = "限时增益"
L["Toggle Raid Tools"] = "切换团队工具"
L["Toggles the Raid Tools panels, in or out of combat.\n\nLeft-click to set a keybind.\nRight-click to unbind."] = "在战斗内外切换团队工具面板。\n\n左键点击设置快捷键。\n右键点击解除绑定。"
L["Two Windows"] = "双窗口"
L["Uninstall & Reload"] = "卸载并重载"
L["Uninstall EUI"] = "卸载 EUI"
L["Up Left"] = "左上"
L["Up Right"] = "右上"
L["Use another action menu's keybind while that menu is not loaded. Both menus must be assigned to different specs."] = "在另一个动作菜单未载入时使用其快捷键。两个菜单必须分配给不同的专精。"
L["Which buffs enemy nameplates show. Fine-tune it on the Aura Filters page."] = "敌方姓名板显示哪些增益。可在光环筛选页面中微调。"
L["Which ends of the bar show the gryphons."] = "进度条的哪一端显示狮鹫。"
L["XP Bar Style"] = "经验条样式"
L["XP color"] = "经验颜色"
L["Every module runs on native Wrath APIs. Retail looks and settings were ported wherever the 3.3.5a client supports them, and Retail-only systems were left out. Notes are grouped by module, newest first, and each header shows that module's backport version."] = "所有模块都运行在巫妖王之怒原生 API 上。只要 3.3.5a 客户端支持，正式服的外观和设置都已移植，仅限正式服的系统则被省略。说明按模块分组，最新的在前，每个标题显示该模块的移植版本。"
L["Icons beside each enemy for every crowd control category they are under or recovering from: green means the next one lasts half as long, yellow a quarter, red immune. A timer shows the 18 second reset."] = "每个敌人旁的图标显示其正处于或正在恢复的每种控制类别：绿色表示下一次持续时间减半，黄色为四分之一，红色为免疫。计时器显示 18 秒的重置时间。"
L["A health bar for each enemy pet under its owner's frame. Left-click targets the pet, right-click sets focus."] = "每个敌方宠物在其主人框体下方有一条生命条。左键点击选中宠物，右键点击设为焦点。"
L["Enemy frames for arena1-5 with class colored health, power and cast bars plus a highlight on your target. Left-click targets, right-click sets focus. There is no Retail equivalent."] = "arena1-5 的敌方框体，带职业着色的生命条、能量条和施法条，并高亮你的目标。左键点击选中，右键点击设为焦点。正式服没有对应功能。"
L["The class icon swaps to the highest priority crowd control or immunity with a spiral and timer, and the PvP trinket icon tracks its 2 minute cooldown from the combat log."] = "职业图标会切换为优先级最高的控制或免疫效果，并带有旋转动画和计时；PvP 饰品图标会从战斗记录中追踪其 2 分钟冷却。"
L["Bar Texture lists textures from SharedMedia and other addons using LibSharedMedia"] = "条纹理列出来自 SharedMedia 和其他使用 LibSharedMedia 的插件的纹理"
L["Enemies beyond your class's 30-40 yard spell range fade to a chosen opacity"] = "超出你职业 30-40 码法术距离的敌人会淡化至所选不透明度"
L["Preview 2 to 5 sample frames in Unlock Mode, while the options page is open, or with /earena test"] = "在解锁模式中、选项页面打开时或使用 /earena test 预览 2 到 5 个示例框体"
L["Frames stay up while an enemy is stealthed or out of sight, dimmed and marked Unseen"] = "敌人潜行或不在视野中时框体保持显示，变暗并标记为未见"
L["Optionally hides Blizzard's arena frames while these are in use"] = "可选择在使用这些框体时隐藏暴雪的竞技场框体"
L["The Debuff Filter gets Raid Debuffs and Own and Raid Debuffs, with the same raid debuff list as the Unit Frames."] = "减益效果筛选新增团队减益以及自己的和团队减益，使用与单位框体相同的团队减益列表。"
L["Choose which buffs enemy nameplates show: Timed Buffs, Only Dispellable or Show All, which shows every buff."] = "选择敌方姓名板显示哪些增益：限时增益、仅可驱散或显示全部（显示所有增益）。"
L["Every nameplate text has an Outline choice under its Size: None, Outline, Thick Outline or Shadow, or keep the module default. Covers names, level, health, Target of Target, cast texts, aura text and friendly names."] = "每个姓名板文本在其大小下方都有轮廓选项：无、轮廓、粗轮廓或阴影，或保持模块默认。涵盖名称、等级、生命值、目标的目标、施法文本、光环文本和友方名称。"
L["Cast bars now fill every frame instead of stepping with each nameplate refresh. The spark and timer move smoothly too, and the extra work stops when no cast is visible."] = "施法条现在每帧填充，而不是随每次姓名板刷新跳变。火花和计时器也平滑移动，且没有可见施法时会停止额外运算。"
L["Core Text Positions offers all Retail texts: Enemy Name, Level | Name, Target of Target, Health % and Health # with their combined variants. Each text's cog sets its size."] = "核心文本位置提供所有正式服文本：敌方名称、等级 | 名称、目标的目标、生命值 % 和生命值 # 及其组合变体。每个文本的齿轮可设置其大小。"
L["Health and cast bars offer the EllesmereUI textures (Melli, Atrocity, Fade, Matte and more), as on Retail"] = "生命条和施法条提供 EllesmereUI 纹理（Melli、Atrocity、Fade、Matte 等），与正式服相同"
L["Health and cast bar textures include textures from SharedMedia and other addons"] = "生命条和施法条纹理包括来自 SharedMedia 和其他插件的纹理"
L["Display and Colors show a live preview plate; click any part of it to jump to its setting"] = "显示和颜色页面会显示实时预览姓名板；点击其任意部分即可跳转到对应设置"
L["Retail bar size, colors, threat modes, cast colors, target arrows and Execute Pulse Glow"] = "正式服的条大小、颜色、仇恨模式、施法颜色、目标箭头和斩杀脉冲发光"
L["Each slot holds one element; auras, raid marker and classification can also sit below the cast bar"] = "每个槽位放置一个元素；光环、团队标记和分类也可以放在施法条下方"
L["Health # uses Blizzard style abbreviations (1.2K, 12K, 1.2M) with an optional % decimal"] = "生命值 # 使用暴雪风格的缩写（1.2K、12K、1.2M），可选显示 % 小数"
L["A profile imported from Retail no longer blows the target nameplate up to fill the screen."] = "从正式服导入的配置不再把目标姓名板放大到占满屏幕。"
L["Border None now hides only the borders, not the cast bar text, timer, shield and kick mark."] = "边框选择“无”时现在只隐藏边框，不再隐藏施法条文本、计时器、护盾和打断标记。"
L["The options preview plate no longer disappears after switching tabs or closing the panel."] = "选项预览姓名板在切换标签页或关闭面板后不再消失。"
L["The Interrupt on CD cast color now shows while your interrupt recharges, as on Retail, instead of the reverse."] = "“打断冷却中”施法颜色现在在你的打断技能冷却时显示，与正式服一致，而不是相反。"
L["Raid and party names each get their own outline: None, Outline, Thick Outline, Shadow, or the Raid Frames font default."] = "团队和小队名称各自有独立的轮廓：无、轮廓、粗轮廓、阴影，或团队框体字体默认值。"
L["A new Group Layout stacks two raid groups per column, then starts the next column to the right, so a 20-player raid forms a 2x2 block."] = "新的队伍布局每列堆叠两个团队小组，然后向右开始下一列，因此 20 人团队会形成 2x2 方块。"
L["Ready check icons appear above debuffs and keep each player result for ten seconds after the check finishes."] = "就位确认图标显示在减益上方，并在确认结束后保留每名玩家的结果十秒。"
L["The debuff displayed in the central Raid Debuff icon is excluded from the regular debuff bar, leaving room for other debuffs."] = "显示在中央团队减益图标中的减益会从普通减益栏中排除，为其他减益留出空间。"
L["Raid and party frames dim outside range on Wrath, including in combat. Dim Out of Range and Out of Range Alpha control the fade."] = "在巫妖王之怒中，团队和小队框体在超出范围时变暗，包括战斗中。“超出范围时变暗”和“范围外不透明度”控制淡化效果。"
L["A large icon in the middle of each frame for important ICC, Ruby Sanctum, Trial of the Crusader, Ulduar and Naxxramas debuffs, highest priority first, with timer, stacks and a dispel colored border. Without a listed debuff it can show a dispellable one instead."] = "每个框体中央的大图标，显示冰冠堡垒、红玉圣殿、十字军的试炼、奥杜尔和纳克萨玛斯的重要减益，按优先级从高到低，带计时、层数和驱散颜色边框。没有列表中的减益时，可改为显示可驱散的减益。"
L["Dispel Overlay styles with opacity, a dispel colored Frame Border, Type Icon Position, per-type Dispel Colors and Only Show Dispellable."] = "带不透明度的驱散叠加样式、驱散颜色的框体边框、类型图标位置、按类型的驱散颜色以及仅显示可驱散。"
L["Overlay, Real or No Preview. The preview opens while the Raid or Party page is open and closes when you leave it, close the panel or enter combat."] = "叠加、真实或无预览。打开团队或小队页面时开启预览，离开页面、关闭面板或进入战斗时关闭。"
L["Enemy casts show as icons on the party or raid member being cast at, with a cast sweep and interruptible border. Party defaults to When Healing; each raid layout has its own mode. Wrath has no spell target, so the victim is the caster's target, and only enemies someone in the group targets are seen"] = "敌方施法会以图标显示在被施法的小队或团队成员上，带施法动画和可打断边框。小队默认为“治疗时”；每种团队布局有各自的模式。巫妖王之怒没有法术目标，因此受害者为施法者的目标，且只能看到队伍中有人选中的敌人"
L["Damage shields show on the health bar as on Retail: Absorb Style, Opacity, Color, Placement and Show Overshield. Wrath does not report shield amounts, so they are estimated from the combat log"] = "伤害护盾像正式服一样显示在生命条上：吸收样式、不透明度、颜色、放置和显示过量护盾。巫妖王之怒不报告护盾数值，因此根据战斗记录估算"
L["Health Bar Texture lists textures from SharedMedia and other addons, also in the aura indicator preview"] = "生命值条纹理列出来自 SharedMedia 和其他插件的纹理，光环指示器预览中也是如此"
L["25-Player Preview"] = "25 人预览"
L["The Unlock Mode and options previews open on the 25-player layout instead of 40"] = "解锁模式和选项预览以 25 人布局打开，而不是 40 人"
L["Health color modes, backgrounds, threat, target and hover borders, text and icon placement"] = "生命颜色模式、背景、仇恨、目标和悬停边框、文本和图标位置"
L["Incoming heals and resurrections from players who use a HealComm addon"] = "来自使用 HealComm 插件的玩家的预计治疗和复活"
L["Main Tank, Pet and Friendly Boss frames plus Healer Mana text, each with an Unlock Mode mover"] = "主坦克、宠物和友方首领框体以及治疗者法力文本，各自带有解锁模式移动框"
L["The Party page has a LAYOUT section with Horizontal Frames"] = "小队页面新增布局区段，包含水平框体"
L["Ready check icons show a green check for players who accepted and for the one who started the check, instead of a red X when the check ended."] = "就位确认图标对已接受的玩家和发起确认的玩家显示绿色对勾，而不是在确认结束时显示红色叉号。"
L["The party leader icon shows on the leader only instead of on several party members."] = "小队队长图标只显示在队长身上，而不是多个小队成员身上。"
L["Set Focus and Clear Focus in the raid and party frame menu work out of combat without the 'blocked from an action' popup; in combat they are hidden, use a Click Casting Focus binding there."] = "团队和小队框体菜单中的设置焦点和清除焦点在脱离战斗时可用，不再弹出“被阻止执行动作”提示；战斗中它们被隐藏，请在战斗中使用点击施法的焦点绑定。"
L["Ready check icons show on raid and party frames again."] = "就位确认图标重新显示在团队和小队框体上。"
L["Hide Sated / Exhaustion also hides the 81005 Bloodlust lockout debuff."] = "隐藏心满意足 / 精疲力竭也会隐藏 81005 嗜血锁定减益。"
L["Pet frames no longer throw a SecureTemplates strupper error when they first appear."] = "宠物框体首次出现时不再抛出 SecureTemplates strupper 错误。"
L["The Buffs/Debuffs editor's Add New menu no longer closes on the first click."] = "增益/减益编辑器的“新建”菜单在第一次点击时不再关闭。"
L["Element Options for raid and party frames now open the matching settings."] = "团队和小队框体的元素选项现在会打开对应的设置。"
L["Profile strings exported from Retail EllesmereUI import everything this client supports: each module keeps its current settings and takes the Retail values it understands. Retail-only modules, spec setups and Cooldown Manager spells are skipped, and chat reports how many settings came in."] = "从正式服 EllesmereUI 导出的配置字符串会导入此客户端支持的全部内容：每个模块保留当前设置并采用其能理解的正式服数值。仅限正式服的模块、专精设置和冷却管理器法术会被跳过，聊天中会报告导入了多少项设置。"
L["A button on Global Settings puts back the game settings EUI changed (nameplate, minimap, chat and tooltip options, chat font sizes and keys Quickdraw took), then turns EUI off for this character and reloads. Your profiles are kept."] = "全局设置中的一个按钮可还原 EUI 更改过的游戏设置（姓名板、微缩地图、聊天和鼠标提示选项、聊天字体大小以及快速菜单占用的按键），然后为此角色关闭 EUI 并重载。你的配置会保留。"
L["A drawn cooldown sweep for modules that want round or colored swipes; the Wrath client's own swipe is always a dark square. Cooldown Manager uses it first."] = "为需要圆形或彩色冷却动画的模块绘制的冷却动画；巫妖王之怒客户端自带的冷却动画始终是深色方块。冷却管理器最先使用它。"
L["When a guild or group member runs a newer EllesmereUI release, chat tells you once per session. Type /euiupdate for the download link. Wrath has no internet access, so the news comes from other EUI users."] = "当公会或队伍成员运行更新的 EllesmereUI 版本时，聊天中每次会话会提示你一次。输入 /euiupdate 获取下载链接。巫妖王之怒无法访问互联网，因此消息来自其他 EUI 用户。"
L["The Locales addon provides community translations for all original Wrath client languages, with English fallback and Lua 5.1 formatting."] = "Locales 插件为所有原版巫妖王之怒客户端语言提供社区翻译，带英文回退和 Lua 5.1 格式。"
L["The collapsed menu displays the original Ellesmere E logo with the UI accent color and a working close icon on the Wrath client."] = "在巫妖王之怒客户端上，折叠菜单显示原版 Ellesmere E 标志，使用界面强调色，并带有可用的关闭图标。"
L["Fonts, bar textures and sounds that other addons register with LibSharedMedia appear in the EllesmereUI menus, including ones registered after login."] = "其他插件通过 LibSharedMedia 注册的字体、条纹理和声音会出现在 EllesmereUI 菜单中，包括登录后注册的。"
L["A shared outline picker for individual texts: None, Outline, Thick Outline or Shadow, with Module Default following the Fonts page. Text keeps its color when you switch."] = "用于单个文本的通用轮廓选择器：无、轮廓、粗轮廓或阴影，模块默认跟随字体页面。切换时文本保持其颜色。"
L["The Incompatible Addon popup can disable the other addon or the affected EllesmereUI module and reload. Okay and Don't show again work as before."] = "不兼容插件弹窗可以禁用另一个插件或受影响的 EllesmereUI 模块并重载。“确定”和“不再显示”与以前一样有效。"
L["Per-spec setting groups with automatic capture and their own Unlock Mode layouts, plus conditional overrides for dungeons, raids, arenas, battlegrounds, solo play and out of combat."] = "按专精的设置组，带自动捕获和各自的解锁模式布局，以及针对地下城、团队副本、竞技场、战场、单人游戏和脱离战斗的条件覆盖。"
L["The Esc menu has EllesmereUI and EUI Unlock Mode buttons, shown by default. Both follow the EUI Buttons setting in Global Settings."] = "Esc 菜单有 EllesmereUI 和 EUI 解锁模式按钮，默认显示。两者都遵循全局设置中的 EUI 按钮设置。"
L["With Show Spell ID on Tooltip on, item tooltips add the item ID and icon file name. Each line has its own toggle"] = "开启“在提示中显示法术 ID”时，物品鼠标提示会添加物品 ID 和图标文件名。每行都有独立开关"
L["Raid and Unit Frames read absorb shields from a shared estimate: rank base value plus your own spell power, minus what each shield absorbs in the combat log. Clients with a native absorb API use it directly"] = "团队框体和单位框体从共享估算中读取吸收护盾：等级基础值加上你自己的法术强度，减去战斗记录中每个护盾吸收的量。拥有原生吸收 API 的客户端会直接使用它"
L["Arena Frames joins the sidebar, first-use list, profiles, spec overrides, module fonts and search"] = "竞技场框体加入侧栏、首次使用列表、配置、专精覆盖、模块字体和搜索"
L["Profile strings and shared exports work again"] = "配置字符串和共享导出恢复正常"
L["An ice blue options theme; Match Accent to Theme follows each theme's palette"] = "冰蓝色选项主题；强调色匹配主题会跟随每个主题的配色"
L["Lights, beams, music and spin on boss kills, arena and battleground wins, Bloodlust/Heroism and level ups"] = "在击杀首领、赢得竞技场和战场、嗜血/英勇以及升级时显示灯光、光束、音乐和旋转效果"
L["Show Spell ID on Tooltip covers spells, action buttons, auras and chat links (off by default)"] = "“在提示中显示法术 ID”涵盖法术、动作按钮、光环和聊天链接（默认关闭）"
L["The options sidebar shows the combined memory used by all loaded EllesmereUI addons"] = "选项侧栏显示所有已载入 EllesmereUI 插件的总内存占用"
L["The sidebar sync button opens its profile list again instead of erroring when you have more than one profile."] = "当你有多个配置时，侧栏同步按钮会重新打开其配置列表，而不是报错。"
L["Retail profile strings bring their element positions: action, XP and menu bars, CDM bars, raid and party frames, chat, damage meter windows, QoL displays, resource bars and the fixed tooltip land where the creator placed them."] = "正式服配置字符串会带上元素位置：动作条、经验条和菜单条、CDM 条、团队和小队框体、聊天、伤害统计窗口、体验优化显示、资源条和固定鼠标提示会放在创建者放置的位置。"
L["Nameplates-only Retail profile strings are recognised as Retail; bar width and height, cast bar height and color, name size and aura sizes carry over."] = "仅含姓名板的正式服配置字符串会被识别为正式服；条宽度和高度、施法条高度和颜色、名称大小和光环大小都会保留。"
L["Unlock Mode: the top bar toggle icons and labels are brighter, so they no longer read dark grey on the banner."] = "解锁模式：顶栏的开关图标和标签更亮，在横幅上不再显示为深灰色。"
L["Set Focus and Clear Focus in right-click menus from EUI frames go through a secure button out of combat instead of being blocked; in combat they are hidden."] = "EUI 框体右键菜单中的设置焦点和清除焦点在脱离战斗时通过安全按钮执行，而不再被阻止；战斗中它们被隐藏。"
L["Unlock Mode: the arrow keys move the selected element 1 pixel again (hold Shift for 100)."] = "解锁模式：方向键再次将所选元素移动 1 像素（按住 Shift 移动 100）。"
L["Works alongside !!!ClassicAPI: its clipping and mask functions are no longer used on EUI frames, so animated glows and the options panel stop erroring."] = "可与 !!!ClassicAPI 一起使用：EUI 框体不再使用其裁剪和遮罩函数，因此动画发光和选项面板不再报错。"
L["Opening the options no longer errors with \"attempt to index local 'mask'\" on clients where another addon adds an empty mask function."] = "在其他插件添加了空遮罩函数的客户端上，打开选项不再报错 \"attempt to index local 'mask'\"。"
L["The profile Import and Export boxes no longer error with \"attempt to call method 'GetNumLines'\" and scroll to fit long strings."] = "配置导入和导出框不再报错 \"attempt to call method 'GetNumLines'\"，并可滚动以容纳长字符串。"
L["The collapsed menu shows the Ellesmere E logo again instead of a plain black circle."] = "折叠菜单重新显示 Ellesmere E 标志，而不是一个纯黑圆圈。"
L["Action button tooltips show the real spell ID instead of the spellbook slot."] = "动作按钮鼠标提示显示真实的法术 ID，而不是法术书槽位。"
L["Fixed an \"attempt to call global 'issecretvalue'\" error from Cooldown Manager glows before the options panel was first opened."] = "修复了在首次打开选项面板之前，冷却管理器发光导致的 \"attempt to call global 'issecretvalue'\" 错误。"
L["Unlock Mode widget tooltips use Wrath-compatible alpha fades, fixing the SetFromAlpha error on Grow Right."] = "解锁模式控件的鼠标提示使用兼容巫妖王之怒的透明度渐变，修复了向右增长时的 SetFromAlpha 错误。"
L["The options search results list has a fully opaque background with its results drawn above it, so sidebar and page text no longer bleeds into the results."] = "选项搜索结果列表使用完全不透明的背景，结果绘制在其上方，因此侧栏和页面文本不再透到结果中。"
L["Unlock Mode no longer errors on SetMaxLines when it first opens, so element movers appear again."] = "解锁模式首次打开时不再在 SetMaxLines 上报错，元素移动框重新出现。"
L["The Patch Notes reminder dot now lights after each backport update."] = "每次移植版更新后，补丁说明提示红点现在会亮起。"
L["The options search results now draw above the sidebar and page instead of behind them."] = "选项搜索结果现在绘制在侧栏和页面上方，而不是在它们后面。"
L["The Unlock Mode right-click menu no longer closes right after opening when many elements are on screen."] = "屏幕上元素较多时，解锁模式右键菜单不再在打开后立即关闭。"
L["Opening the Raid Frames options no longer causes a stack overflow in Settings Overrides."] = "打开团队框体选项不再导致设置覆盖中的堆栈溢出。"
L["Unlock Mode art, options page icons and the Unlock Mode top bar are now visible and readable."] = "解锁模式美术、选项页面图标和解锁模式顶栏现在可见且清晰可读。"
L["The addon list shows clean module names, grouped under EllesmereUI in addon managers."] = "插件列表显示简洁的模块名称，并在插件管理器中归组到 EllesmereUI 下。"
L["Search Features and Search Module Settings accept typing again."] = "搜索功能和搜索模块设置重新可以输入文字。"
L["Clients whose atlas lookup errors on unknown names (such as custom 3.3.5 clients with Retail UI ports) no longer stop EllesmereUI files from loading."] = "图集查询遇到未知名称会报错的客户端（例如移植了正式服界面的自定义 3.3.5 客户端）不再阻止 EllesmereUI 文件载入。"
L["Like Retail 9.4, the DataBars page opens with a bar selector at the top: rename or delete a bar right in its menu, or pick + Create New DataBar. + New Bar shows the four starter templates as cards, and with no bars yet the page shows them as a card grid."] = "与正式服 9.4 相同，数据条页面顶部有条选择器：直接在其菜单中重命名或删除条，或选择“+ 创建新数据条”。“+ 新条”以卡片形式显示四个起始模板，在还没有任何条时页面会以卡片网格显示它们。"
L["Like Retail 9.4, the options window has a Window Scale slider in its top corner that resizes it in smooth 5% steps; the mouse wheel over it, or Shift + mouse wheel anywhere on the window, works too. The credit to Ellesmere now sits under the close button."] = "与正式服 9.4 相同，选项窗口顶角有窗口缩放滑块，以 5% 的平滑步长调整大小；在滑块上滚动鼠标滚轮，或在窗口任意位置按住 Shift 滚动滚轮也可以。对 Ellesmere 的致谢现在位于关闭按钮下方。"
L["Global Settings opens with Reset ALL EUI Addon Settings and Uninstall EUI side by side, like Retail 9.4. Reset ALL now asks you to type Confirm. Optimize My FPS and Graphics is gone: the graphics settings it changed do not exist on this client."] = "全局设置打开时并排显示“重置所有 EUI 插件设置”和“卸载 EUI”，与正式服 9.4 相同。“重置所有”现在需要你输入 Confirm。“优化我的 FPS 和图形”已移除：它修改的图形设置在此客户端上不存在。"
L["Like Retail 9.4, each look card on the Style page has a menu of the modules using it: tick modules under another look, then press Apply Styles to switch them all with one reload. The menus list only looks this client can draw: Cooldown Manager, Minimap and Damage Meters offer EllesmereUI and Classic WoW UI, Player Aura Bars is gone, and Apply to All skips modules without that look."] = "与正式服 9.4 相同，样式页面上的每张外观卡片都有一个使用该外观的模块菜单：勾选其他外观下的模块，然后按“应用样式”即可一次重载全部切换。菜单只列出此客户端能绘制的外观：冷却管理器、微缩地图和伤害统计提供 EllesmereUI 和经典 WoW UI，玩家光环条已移除，“应用于全部”会跳过没有该外观的模块。"
L["The import page can update your current profile instead of making a new one: tick Import into current profile and the string's selected modules (for example only Nameplates) replace their settings there while the rest of the profile stays."] = "导入页面可以更新你的当前配置，而不是新建一个：勾选“导入到当前配置”，字符串中选中的模块（例如仅姓名板）会替换其中的设置，配置的其余部分保持不变。"
L["The EUI Staff page opens with thanks to Ellesmere and the port staff card with a GitHub link to the releases. The header line crediting Ellesmere opens it."] = "EUI 团队页面开头感谢 Ellesmere，并有移植团队卡片，附带指向发布页面的 GitHub 链接。点击致谢 Ellesmere 的标题行即可打开它。"
L["Custom spell reminders, visibility and sounds are saved separately for each character, independently of shared profiles."] = "自定义法术提醒、可见性和声音按角色单独保存，独立于共享配置。"
L["Optional achievement, trade and guild recruitment filters, plus your own blocked words and phrases."] = "可选的成就、交易和公会招募过滤，以及你自己屏蔽的词语和短语。"
L["Configure repeat timing, sender matching and chat scopes from the new Spam Filter page."] = "在新的垃圾信息过滤页面中配置重复时间、发送者匹配和聊天范围。"
L["Outline menus in the Nameplates and Unit Frames text cogs, and Zone Text Outline in Quality of Life. The Unit Frames preview shows each text's outline."] = "姓名板和单位框体文本齿轮中的轮廓菜单，以及体验优化中的区域文本描边。单位框体预览会显示每个文本的轮廓。"
L["New PETS and DIMINISHING RETURNS sections, plus Fade Out of Range and its opacity under Target and Visibility."] = "新增宠物和递减效果区段，以及目标和可见性下的“超出范围时淡出”及其不透明度。"
L["Announce Interrupts and Accept Invites from Friends & Guild in the GROUP section, and a Disband Group button on Raid Tools."] = "组区段中的通报打断和接受好友和公会的邀请，以及团队工具上的解散队伍按钮。"
L["Bar Display, Menu, Bags & XP Bars and Bar Animations, with a live preview of the selected bar. Click an icon, keybind or count to jump to its setting."] = "条显示、菜单、背包和经验值条以及条动画，带所选条的实时预览。点击图标、快捷键或数量即可跳转到对应设置。"
L["The Raid and Party pages gain the Retail DISPELS section and a Preview Mode (Real, Overlay or No Preview) at the top."] = "团队和小队页面新增正式服的驱散区段，并在顶部新增预览模式（真实、叠加或无预览）。"
L["Party and Raid pages gain a TARGETED SPELLS section: mode, preview, icon size, maximum icons, position, growth, offsets, cast swipe, cast timer and interruptible colors."] = "小队和团队页面新增目标法术区段：模式、预览、图标大小、最大图标数、位置、增长方向、偏移、施法动画、施法计时器和可打断颜色。"
L["Raid Frames (Party and Raid) and Unit Frames (player, target, focus) gain an ABSORBS section for the estimated shields, with a shield in the Unit Frames preview."] = "团队框体（小队和团队）和单位框体（玩家、目标、焦点）新增吸收区段用于估算护盾，单位框体预览中显示护盾。"
L["CDM Bars now opens with Retail's bar dropdown (rename or delete custom bars, add Cooldowns, Utility, Buff or FocusKick bars) and the selected bar's icons: drag to reorder, click an icon to edit it, middle-click to remove it, and use + to add spells or buffs."] = "CDM 条现在打开时显示正式服的条下拉菜单（重命名或删除自定义条，添加冷却时间、实用、增益或焦点打断条）以及所选条的图标：拖动以重新排序，点击图标进行编辑，中键点击移除，使用 + 添加法术或增益。"
L["Hide server announcements such as \"Name the level 11 Gnome Warrior has been slain by ... in Westfall\", optionally keeping deaths from a chosen level up visible."] = "隐藏服务器公告，例如 \"Name the level 11 Gnome Warrior has been slain by ... in Westfall\"，可选择保留从所选等级起的死亡公告。"
L["The FocusKick Cast Sound and the Chat sounds list EllesmereUI and SharedMedia sounds, and the Textures page links Damage Meters to its per-window Bar Texture"] = "焦点打断施法音效和聊天音效列出 EllesmereUI 和 SharedMedia 声音，纹理页面将伤害统计链接到其各窗口的条纹理"
L["New dropdown at the top of Icons, with a link to apply it to every bar. The preview shows the shape."] = "图标顶部新增下拉菜单，附带应用到所有条的链接。预览会显示形状。"
L["Boss Debuff Icon, Icon Size, Icon Offset Y and Show Dispellable When No Boss Debuff under Dispels"] = "驱散下的首领减益图标、图标大小、图标纵向偏移和无首领减益时显示可驱散"
L["General, Layout, Health and Power, Text, Icons, Cast Bar and Target and Visibility sections"] = "常规、布局、生命值和能量、文本、图标、施法条以及目标和可见性区段"
L["Display, Extras and Wrath Inventory settings, including Delete Saved Character"] = "显示、额外功能和巫妖王之怒背包设置，包括删除已保存角色"
L["Class icon themes, class colored names, borders, accent colors, faction banners and invite auto-accept"] = "职业图标主题、职业着色名称、边框、强调色、阵营横幅和自动接受邀请"
L["Display, Colors, General and Aura Filters with inline color swatches and cog menus"] = "显示、颜色、常规和光环筛选，带内联颜色样本和齿轮菜单"
L["Quick Loot, Auto-Fill Delete Confirmation, Auto Repair and Auto Sell Junk in the Retail layout"] = "正式服布局中的快速拾取、自动填写删除确认、自动修理和自动出售垃圾"
L["Display, Colors and Extras sections with inline swatches and auto accept and turn-in cogs"] = "显示、颜色和额外功能区段，带内联颜色样本以及自动接受和交任务齿轮"
L["Wrath spell icons, real cast times and the same faction and portrait art as the live frames"] = "巫妖王之怒法术图标、真实施法时间，以及与实际框体相同的阵营和头像美术"
L["The Active Profile dropdown shows the rename, delete and keybind icons on each profile again."] = "当前配置下拉菜单重新在每个配置上显示重命名、删除和快捷键图标。"
L["Dropdowns open again with !!!ClassicAPI installed; its clipping function no longer moves the menus into an empty scroll frame."] = "安装 !!!ClassicAPI 后下拉菜单重新可以打开；其裁剪函数不再把菜单移到空的滚动框架中。"
L["Resetting Global Settings no longer stops partway with an error and reloads the UI again."] = "重置全局设置不再中途报错停止，并会重新重载界面。"
L["Options that do nothing on the Wrath client are hidden: image sharpening, Lag Tolerance, Combat Text Size, Swiftmend dim, Slug outline, class resource dark mode and colors, Retail-only class and power colors, and cursor ring textures."] = "在巫妖王之怒客户端上无效的选项已隐藏：图像锐化、延迟容限、战斗文本大小、迅捷治愈变暗、Slug 轮廓、职业资源深色模式和颜色、仅限正式服的职业和能量颜色，以及指针环纹理。"
L["Global Settings no longer shows the Gamepad page, which has nothing to control on the Wrath client."] = "全局设置不再显示手柄页面，因为它在巫妖王之怒客户端上没有可控制的内容。"
L["Max Camera Distance saves and keeps its value instead of resetting to 1.0, and goes up to 4 like the Wrath client allows."] = "最大镜头距离会保存并保持其数值，而不再重置为 1.0，并且最高可达巫妖王之怒客户端允许的 4。"
L["CDM Bars and Tracking Bars open without an \"attempt to call field 'disabled'\" error, and nine toggles show their tooltips again."] = "CDM 条和追踪条打开时不再出现 \"attempt to call field 'disabled'\" 错误，九个开关重新显示其提示。"
L["Chat > Spam Filter: the chat type settings stay usable when only the trade or recruitment filter is on, and the tooltips explain what each one covers."] = "聊天 > 垃圾信息过滤：仅开启交易或招募过滤时，聊天类型设置仍可使用，提示会说明每项涵盖的内容。"
L["Opening the options no longer makes later Blizzard actions risk being blocked in EllesmereUI's name."] = "打开选项后，之后的暴雪操作不再有以 EllesmereUI 名义被阻止的风险。"
L["Checklist menus such as Visibility tick and untick their boxes as soon as they are clicked, even when the module's live update runs into a problem, instead of only after closing and reopening the menu."] = "可见性等清单菜单在点击后立即勾选和取消勾选，即使模块的实时更新出现问题也是如此，而不是只在关闭并重新打开菜单后才更新。"
L["Dropdown lists, checklists and other option popups draw their items above their own background, on a solid background, instead of showing faded items with the page bleeding through."] = "下拉列表、清单和其他选项弹窗将项目绘制在自身背景之上，使用不透明背景，而不是显示褪色的项目并透出页面。"
L["The Style page now keeps the Unit Frames health colors per look, so switching between Classic WoW UI and the EllesmereUI look keeps each one's colors."] = "样式页面现在按外观保存单位框体的生命颜色，因此在经典 WoW UI 和 EllesmereUI 外观之间切换时会保留各自的颜色。"
L["The Unit Frames preview and power color swatches show the original game power colors under Classic WoW UI."] = "在经典 WoW UI 下，单位框体预览和能量颜色样本显示原版游戏的能量颜色。"
L["Each Core Text Position row, Spell Name, Cast Timer and Friendly Names now has its own gear for the outline instead of hiding it in the size popup."] = "每个核心文本位置行、法术名称、施法计时器和友方名称现在都有各自的轮廓齿轮，而不是藏在大小弹窗中。"
L["Pressing Esc to close Blizzard windows no longer shows \"EllesmereUIOptions has been blocked from an action\"."] = "按 Esc 关闭暴雪窗口时不再显示 \"EllesmereUIOptions has been blocked from an action\"。"
L["Combat damage, healing, periodic and pet damage toggles use Wrath's own combat text settings."] = "战斗伤害、治疗、周期性效果和宠物伤害开关使用巫妖王之怒自带的战斗文本设置。"
L["Hidden option widgets no longer take keyboard focus after other windows close with Escape."] = "其他窗口通过 Esc 关闭后，隐藏的选项控件不再获取键盘焦点。"
L["Dragging or typing in a slider no longer errors."] = "拖动滑块或在滑块中输入不再报错。"
L["The settings panel opens on clients whose atlas lookup errors on unknown names, instead of failing with an 'NS' error."] = "在图集查询遇到未知名称会报错的客户端上，设置面板可以打开，而不再以“NS”错误失败。"
L["Displays has a ZONE TEXT section with Move Zone Text."] = "显示页面有区域文本区段，包含移动区域文字。"
L["Raid Tools no longer has a BOSS MOD BARS section: AbilityTimeline's Sources options hide DBM and BigWigs bars."] = "团队工具不再有首领模组计时条区段：AbilityTimeline 的 Sources 选项可隐藏 DBM 和 BigWigs 计时条。"
L["The Retail raid panel: show it never, in raids, in any group or always, as a resizable Compact Band, one or two windows, or only one part. It can start as a small icon, opens and closes with a keybind even in combat, and has three pull timers, Convert and Disband. Reinvite removes everyone and invites them back to the same kind of group, and Convert to Party rebuilds a raid of five or fewer as a party the same way. Shift + Left Click a marker to place its world marker when the marker item is in your bags, or Shift + Left Click the clear icon to reset world markers. In a raid it only shows for the leader and assistants."] = "正式服团队面板：可设置为从不显示、在团队中、在任意队伍中或始终显示，形式可为可调整大小的紧凑条带、单窗口或双窗口，或仅一部分。它可以以小图标启动，可用快捷键打开和关闭（战斗中也可），并有三个开怪倒数、转化和解散。重新邀请会移出所有人并重新邀请进同类型的队伍，转化为小队会以相同方式将五人或更少的团队重建为小队。当标记物品在背包中时，Shift + 左键点击标记可放置其世界标记，或 Shift + 左键点击清除图标以重置世界标记。在团队中只对团长和助理显示。"
L["One key casts Misdirection or Tricks of the Trade on your focus, the tank (typed name, Main Tank or tank role), your friendly target or your pet. An icon shows who it will go to, the buff timer and the cooldown. Bind it in Key Bindings."] = "一个按键即可对你的焦点、坦克（输入的名称、主坦克或坦克职责）、友方目标或宠物施放误导或嫁祸诀窍。图标显示施放对象、增益计时和冷却。在按键设置中绑定。"
L["Damage taken, healing, avoids and entering or leaving combat scroll above the player frame instead of Blizzard's combat text, with Straight, Fountain or Static animations, colors per type and a mover in Unlock Mode."] = "受到的伤害、治疗、闪避以及进入或离开战斗会在玩家框体上方滚动显示，取代暴雪的战斗文本，提供直线、喷泉或静态动画，按类型设置颜色，并在解锁模式中有移动框。"
L["Picks an NPC's only dialog option for you. Hold Shift to skip it; instances and NPCs with quests to take or turn in are left alone. Its cog can also skip past low level quests."] = "自动为你选择 NPC 唯一的对话选项。按住 Shift 可跳过；副本和有任务可接或可交的 NPC 不受影响。其齿轮还可跳过低等级任务。"
L["An arrow next to the To box lists your alts on this realm and faction, guild members and the last names you mailed. Click a name to fill it in."] = "收件人框旁的箭头会列出你在此服务器和阵营的小号、公会成员以及最近寄信的名字。点击名字即可填入。"
L["Pick None, Outline, Thick Outline or Shadow for the zone, sub-zone and PvP text shown when entering an area. Blizzard Default keeps the game's own font."] = "为进入区域时显示的区域、子区域和 PvP 文本选择无、轮廓、粗轮廓或阴影。暴雪默认保持游戏自带字体。"
L["Posts the spell you or your pet interrupted, with a spell link, to Say, Emote, Party or Raid. Party and Raid switch to the battleground channel inside battlegrounds."] = "将你或你的宠物打断的法术（附法术链接）发送到说、表情、小队或团队频道。在战场中，小队和团队会切换为战场频道。"
L["Group invites from your friends list and guildmates are accepted automatically, unless you are already grouped or queued in the Dungeon Finder."] = "自动接受来自好友列表和公会成员的组队邀请，除非你已在队伍中或正在地下城查找器中排队。"
L["A Disband button on Raid Tools removes everyone from your raid or party after a confirmation. Leader only, never in combat."] = "团队工具上的解散按钮在确认后将所有人移出你的团队或小队。仅限队长，战斗中不可用。"
L["Loots everything instantly even with Blizzard's Auto Loot off; hold Shift to see the loot window. Locked slots such as group rolls and master loot are skipped."] = "即使关闭了暴雪的自动拾取也会立即拾取全部物品；按住 Shift 可查看拾取窗口。队伍掷骰和队长分配等锁定的槽位会被跳过。"
L["FPS and latency, secondary stats, durability warning, combat and death alerts, a crosshair and a new target distance text, all movable in Unlock Mode."] = "FPS 和延迟、次要属性、耐久度警告、战斗和死亡提醒、准星以及新的目标距离文本，均可在解锁模式中移动。"
L["The FPS counter's new default Text Color, Quality, turns FPS and each latency value green, yellow or red (60/30 fps, 100/250 ms). Custom and Class Color remain available."] = "FPS 计数器新的默认文本颜色“品质”会将 FPS 和每个延迟值显示为绿色、黄色或红色（60/30 fps，100/250 ms）。自定义和职业颜色仍然可用。"
L["Alert sounds from SharedMedia packs that load after Quality of Life play too"] = "在体验优化之后载入的 SharedMedia 包中的提醒音效也可以播放"
L["An Open All button takes items and gold one letter at a time, skipping COD and GM mail"] = "“全部打开”按钮逐封收取物品和金币，跳过货到付款和 GM 邮件"
L["With Send Mail open, Shift-click a bag item to attach it and matching items"] = "打开发送邮件时，Shift 点击背包物品可将其及相同物品附加到邮件"
L["Opens lootable containers one at a time out of combat (off by default)"] = "在脱离战斗时逐个打开可拾取的容器（默认关闭）"
L["A Train All button beside Train shows how many spells are available and the total cost"] = "“训练”旁的“全部训练”按钮显示可学习的法术数量和总花费"
L["Pull timer length, DBM/BigWigs broadcast and a chat countdown"] = "开怪倒数时长、DBM/BigWigs 广播和聊天倒数"
L["Raid Tools keeps its size after importing a Retail profile."] = "导入正式服配置后，团队工具保持其大小。"
L["Shift-click mail attach no longer replaces the bag item click handler, so bag clicks stay free of taint."] = "Shift 点击邮件附件不再替换背包物品的点击处理程序，因此背包点击不会被污染。"
L["Hiding DBM and BigWigs bars while AbilityTimeline is active moved to AbilityTimeline itself, as on Retail: Hide DBM bars and Hide BigWigs bars on its Sources page. The Raid Tools option is gone."] = "AbilityTimeline 启用时隐藏 DBM 和 BigWigs 计时条的功能已移至 AbilityTimeline 本身，与正式服相同：在其 Sources 页面中使用 Hide DBM bars 和 Hide BigWigs bars。团队工具中的该选项已移除。"
L["Logging out, exiting, releasing spirit and other Blizzard confirmation popups no longer trigger the \"EllesmereUIQoL has been blocked from an action only available to the Blizzard UI\" message."] = "登出、退出、释放灵魂以及其他暴雪确认弹窗不再触发 \"EllesmereUIQoL has been blocked from an action only available to the Blizzard UI\" 消息。"
L["The zone name no longer appears in the middle of the screen at small UI scales. It now sits fixed at the top (X 9 / Y 322 from screen center), with no Unlock Mode mover."] = "在较小的界面缩放下，区域名称不再出现在屏幕中央。它现在固定在顶部（距屏幕中心 X 9 / Y 322），没有解锁模式移动框。"
L["Show Player Buffs puts the hovered player's buffs as icons beside the tooltip, with position, size, icons per row and offsets."] = "显示玩家增益会将悬停玩家的增益以图标显示在鼠标提示旁，可设置位置、大小、每行图标数和偏移。"
L["Hovering a stat in the character sheet sidebar glows the equipped items that give it."] = "在角色面板侧栏中悬停某项属性时，提供该属性的已装备物品会发光。"
L["Inspect Enchants and Missing Enhancements"] = "观察附魔和缺失强化"
L["Inspect enchants show as an icon with the name on hover, or as names tinted by item quality, in their own size. At max level, red badges flag missing enchants, empty sockets and a missing belt buckle, as on your character sheet."] = "观察附魔以图标显示（悬停时显示名称），或以按物品品质着色的名称显示，并有独立大小。满级时，红色徽章标记缺失的附魔、空插槽和缺失的腰带扣，与你的角色面板相同。"
L["Saving an equipment set rebuilds the native icon picker even when already open, preventing the PaperDollFrame nil comparison error."] = "保存装备方案时，即使原生图标选择器已打开也会重建它，防止 PaperDollFrame 的 nil 比较错误。"
L["Need, Greed, Disenchant and Pass buttons on loot rolls count what the rest of the group picked. Hover a button to see who, in class colors."] = "拾取掷骰的需求、贪婪、分解和放弃按钮会统计队伍其他成员的选择。悬停按钮可按职业颜色查看是谁。"
L["Player tooltips show GearScore in the GearScoreLite colors, using its formula when it is loaded. GearScoreLite's own line is kept when its option is on."] = "玩家鼠标提示以 GearScoreLite 的颜色显示 GearScore，载入 GearScoreLite 时使用其公式。开启其选项时保留 GearScoreLite 自己的行。"
L["Enchants and gems on every slot, lowest durability, model rotate, pan and zoom, reorderable stat sections and a socket strip that fills sockets from your bags."] = "每个栏位的附魔和宝石、最低耐久度、模型旋转、平移和缩放、可重新排序的属性区段，以及从背包填充插槽的插槽条。"
L["Class colored names and health bar, guild rank, target, item level and a cursor or fixed anchor"] = "职业着色的名称和生命条、公会会阶、目标、物品等级，以及跟随鼠标或固定的锚点"
L["Item levels on inspect, docking beside the character window and a merchant list mode"] = "观察时的物品等级、停靠在角色窗口旁，以及商人列表模式"
L["Resurrect accept glow and a Dungeon Ready countdown bar"] = "复活接受发光和地下城就绪倒计时条"
L["The server's Collections and Wardrobe & Transmog windows join the window skins"] = "服务器的收藏和幻化窗口加入窗口皮肤"
L["Barber Shop, PvP and battlemasters, Arena Registrar, battleground score, minimap and capture bar, Help and GM tickets, GM chat status, breath and fatigue timers, stopwatch, raid pullouts, debug tools and Ace3 config windows"] = "理发店、PvP 和战场军官、竞技场注册员、战场计分板、微缩地图和占领条、帮助和 GM 请求、GM 聊天状态、呼吸和疲劳计时、秒表、团队拖出框体、调试工具和 Ace3 配置窗口"
L["Ready checks no longer leave an empty black panel for the leader or after you answer."] = "就位确认不再为队长或在你回应后留下空的黑色面板。"
L["The character sheet Titles tab lists your known titles again; click one to wear it."] = "角色面板的头衔标签页重新列出你已获得的头衔；点击即可佩戴。"
L["The Guild Message Of The Day popup (and other wide text popups) no longer covers its title and buttons with the input box."] = "公会今日信息弹窗（及其他宽文本弹窗）的输入框不再遮挡其标题和按钮。"
L["The Achievements window no longer darkens the achievement list behind its border."] = "成就窗口不再使边框后的成就列表变暗。"
L["The AddOn List window skin toggle only shows when the client has an AddOn List window."] = "插件列表窗口皮肤开关仅在客户端有插件列表窗口时显示。"
L["Send Mail shows the To, Subject and message boxes again, and the typing cursor stays visible in skinned edit boxes."] = "发送邮件重新显示收件人、主题和正文框，美化后的输入框中的输入光标保持可见。"
L["The fixed tooltip anchor no longer snaps back to its saved spot while you drag it in Unlock Mode."] = "在解锁模式中拖动固定鼠标提示锚点时，它不再跳回已保存的位置。"
L["Auction House: panels and tabs added by Auctionator and other auction addons keep their own look and layout, and the footer Close buttons no longer get an \"x\" over their text."] = "拍卖行：Auctionator 和其他拍卖插件添加的面板和标签页保持各自的外观和布局，底部的关闭按钮不再在文字上叠加 \"x\"。"
L["Talents: the close button and the points footer end at the scroll bar instead of past the window edge."] = "天赋：关闭按钮和点数底栏在滚动条处结束，而不是超出窗口边缘。"
L["Window tabs keep their dark background instead of showing through."] = "窗口标签页保持深色背景，而不是透明显示。"
L["World map: the player arrow, party and raid dots, corpse and quest markers stay on the map art after a map view change during combat, including instance maps."] = "世界地图：战斗中切换地图视图后，玩家箭头、小队和团队圆点、尸体和任务标记仍保留在地图上，包括副本地图。"
L["Native dropdown menus no longer show an empty square at the right of each row."] = "原生下拉菜单不再在每行右侧显示空方块。"
L["Dropdown boxes in Blizzard windows, such as the Dungeon Finder type, end at their arrow instead of past the window edge."] = "暴雪窗口中的下拉框（例如地下城查找器的类型）在其箭头处结束，而不是超出窗口边缘。"
L["Raid Information: the background covers the whole window, including the title, close button, last row and the Extend Raid Lock and Close buttons."] = "团队信息：背景覆盖整个窗口，包括标题、关闭按钮、最后一行以及延长团队锁定和关闭按钮。"
L["The Talents and Glyphs background now ends above the tabs and beside the dual spec tabs."] = "天赋和雕文的背景现在结束于标签页上方和双天赋标签页旁。"
L["The Glyphs tab shows its native parchment background again, aligned with the glyph sockets."] = "雕文标签页重新显示其原生羊皮纸背景，并与雕文插槽对齐。"
L["Sliders in Blizzard windows, such as the Camera and Mouse options, are back to their normal size."] = "暴雪窗口中的滑块（例如镜头和鼠标选项）恢复正常大小。"
L["Hide Until Usable and Hide Outside Form/Stance"] = "可用前隐藏和形态/姿态外隐藏"
L["New Cooldown States: Hide Until Usable shows a spell only while it can be cast and is off cooldown (Overpower, Revenge, Victory Rush, Execute); low resources do not hide it. Hide Outside Form/Stance shows it only in the form or stance it needs. Both can close the gap or keep the place."] = "新的冷却状态：可用前隐藏仅在法术可施放且未冷却时显示（压制、复仇、乘胜追击、斩杀）；资源不足不会使其隐藏。形态/姿态外隐藏仅在所需的形态或姿态中显示。两者都可以收拢空隙或保留位置。"
L["The + menu adds an Empty Slot that keeps a position free on the bar, to group icons."] = "+ 菜单可添加空槽位，在条上保留一个空位置，用于分组图标。"
L["Bars can switch to a Shaped swipe that follows round icons and takes a Swipe Color, instead of the client's dark square sweep."] = "条可以切换为异形冷却动画，贴合圆形图标并使用冷却动画颜色，而不是客户端的深色方形冷却动画。"
L["Cooldowns, Utility and Buffs bars plus custom bars and a FocusKick bar, tracked from your spellbook, cooldowns and auras. Lists are saved per talent group."] = "冷却时间、实用和增益条，以及自定义条和焦点打断条，从你的法术书、冷却和光环中追踪。列表按天赋组保存。"
L["Aura or cooldown bars for player, target, focus or pet with textures, gradients, stack ticks and pandemic glow, arranged in groups."] = "玩家、目标、焦点或宠物的光环或冷却条，带纹理、渐变、层数刻度和 Dot发光，并按组排列。"
L["The + buttons above the bar icons open Retail's add menu: custom spell, item or slot, trinkets, racial, potions and your learned spells, or buffs and buff presets from the gold +"] = "条图标上方的 + 按钮会打开正式服的添加菜单：自定义法术、物品或栏位、饰品、种族技能、药水和你已学会的法术，或从金色 + 中添加增益和增益预设"
L["Passive proc trinkets in the trinket slots show their icon and the internal cooldown after each proc, with the proc buff while it lasts"] = "饰品栏位中的被动触发饰品会显示其图标以及每次触发后的内置冷却，并在触发增益持续期间显示该增益"
L["Tracking bar textures include SharedMedia, and the FocusKick Cast Sound adds EllesmereUI and SharedMedia sounds to the Blizzard ones"] = "追踪条纹理包括 SharedMedia，焦点打断施法音效在暴雪音效基础上加入 EllesmereUI 和 SharedMedia 声音"
L["Light up EllesmereUI, Blizzard or ElvUI action buttons while an aura is active or missing"] = "在光环生效或缺失时点亮 EllesmereUI、暴雪或 ElvUI 动作按钮"
L["Always show, dim, hide on cooldown or when ready, and glow when ready"] = "始终显示、变暗、冷却时或就绪时隐藏，以及就绪时发光"
L["Racials, healthstones, Wrath potions and buffs such as Heroism and Bloodlust"] = "种族技能、治疗石、巫妖王之怒药水以及英勇和嗜血等增益"
L["Show an entry only when a chosen talent is learned"] = "仅在学会所选天赋时显示条目"
L["Utility bar options no longer switch to Buffs after a click, and the Cooldowns bar is no longer replaced by a second Buffs bar."] = "实用条选项在点击后不再切换为增益，冷却时间条也不再被第二个增益条取代。"
L["Racials show once: the Utility bar no longer lists Arcane Torrent (and other racials with class variants) three times."] = "种族技能只显示一次：实用条不再将奥术洪流（以及其他有职业变体的种族技能）列出三次。"
L["A passive trinket in a trinket slot shows its own icon in the options instead of a question mark."] = "饰品栏位中的被动饰品在选项中显示其自身图标，而不是问号。"
L["Bars saved twice or under another bar's name (two Buffs bars and no Cooldowns) are repaired, so each built-in bar keeps its own icons and options."] = "被保存两次或保存在其他条名下的条（两个增益条而没有冷却时间条）已修复，每个内置条都保留自己的图标和选项。"
L["Auto Sized and Even Split bars with Retail backgrounds, borders and screen edge snapping, plus per-block margins, alignment, scale and colors."] = "自动大小和等分条，带正式服的背景、边框和屏幕边缘吸附，以及每个区块的边距、对齐、缩放和颜色。"
L["20 Wrath Blocks"] = "20 个巫妖王之怒区块"
L["Clock, FPS, latency, location, gold history, bags, durability, XP and reputation, dual spec, professions, travel, micro menu, currency and more."] = "时钟、FPS、延迟、位置、金币历史、背包、耐久度、经验和声望、双天赋、专业技能、旅行、微菜单、货币等。"
L["Latency text is green, yellow or red by connection quality by default. A Latency swatch in Text Color switches back to it after picking another color."] = "延迟文本默认根据连接质量显示为绿色、黄色或红色。选择其他颜色后，可通过文本颜色中的延迟色样切换回来。"
L["Column tooltips with clickable rows and secure spell, item and macro lines"] = "带可点击行的列式鼠标提示，以及安全的法术、物品和宏行"
L["Every bar has a mover whose Element Options opens that bar's settings"] = "每个条都有移动框，其元素选项会打开该条的设置"
L["Profiles from 0.2 are converted automatically"] = "0.2 版的配置会自动转换"
L["Bars snapped to a screen edge or set to full length start in their place after login instead of needing Unlock Mode opened and closed."] = "吸附到屏幕边缘或设为全长的条在登录后会出现在原位，而不需要打开并关闭解锁模式。"
L["The cast bar latency zone works for queued spells and remains visible during channels, with configurable color and millisecond text."] = "施法条延迟区域适用于排队的法术，并在引导期间保持可见，可配置颜色和毫秒文本。"
L["Class, Power and Health Bars, Cast Bar, GCD Bar, Swing Timer and Totem Bar, each element with its own Unlock Mode mover. Older profiles migrate once."] = "职业条、能量条和生命条、施法条、公共冷却条、挥砍计时器和图腾条，每个元素都有自己的解锁模式移动框。旧配置会迁移一次。"
L["Main hand, off hand and ranged swings from the combat log, with queued Heroic Strike, Cleave and Maul, parry haste and speed changes."] = "根据战斗记录显示主手、副手和远程攻击，支持排队的英勇打击、顺劈斩和槌击、招架加速和攻速变化。"
L["Bar textures include textures from SharedMedia and other addons"] = "条纹理包括来自 SharedMedia 和其他插件的纹理"
L["Vertical bars, Retail texts, gradients, thresholds, tick marks and smoothing"] = "竖直条、正式服文本、渐变、阈值、刻度标记和平滑"
L["Death Knight rune order and countdowns, combo points, or Blizzard's own art"] = "死亡骑士符文顺序和倒计时、连击点数，或暴雪自带的美术"
L["Channel ticks, latency, total duration and uninterruptible colors"] = "引导跳数、延迟、总持续时间和不可打断颜色"
L["Totem icons and timers, and a movable Call Totem Bar"] = "图腾图标和计时，以及可移动的召唤图腾条"
L["The Call Totem Bar no longer resizes or moves during combat; changes apply when combat ends."] = "召唤图腾条在战斗中不再改变大小或移动；更改会在战斗结束时应用。"
L["The player cast bar shows the channeled spell's name instead of \"Channeling\"."] = "玩家施法条显示引导法术的名称，而不是 \"Channeling\"。"
L["Class icons in the EUI themes, status orbs, notes in the details line, faction banners and hover highlight, with borders and accent colors."] = "EUI 主题中的职业图标、状态圆球、详情行中的备注、阵营横幅和悬停高亮，带边框和强调色。"
L["Accepts group invites from friends, and optionally from guild members, and closes the popup."] = "接受来自好友（可选包括公会成员）的组队邀请并关闭弹窗。"
L["The window stays native but rows still get class icons and colored names"] = "窗口保持原生样式，但各行仍会显示职业图标和着色名称"
L["Auto Accept picks quests from NPC dialogs, with Prevent Multi Quest Accept, and Auto Turn In completes single-reward quests. Hold Shift to skip."] = "自动接受会从 NPC 对话中接取任务，支持防止多任务接受；自动交任务会完成只有单一奖励的任务。按住 Shift 可跳过。"
L["Uses the item of your tracked quest, found in the quest log, and only holds the key while there is an item to use."] = "使用你追踪任务的物品（从任务日志中查找），并且只在有可用物品时占用该按键。"
L["The top line uses the accent color and Line Color tints the header divider"] = "顶部线条使用强调色，线条颜色为标题分隔线着色"
L["/eqt show, /eqt hide and /eqt toggle"] = "/eqt show、/eqt hide 和 /eqt toggle"
L["Clear your focus by clicking the focus frame (Shift + Right Click by default, or Ctrl/Alt + Right Click, Middle Click, Shift + Left Click). Set it on the Focus frame page. Works in combat."] = "点击焦点框体即可清除焦点（默认为 Shift + 右键，也可为 Ctrl/Alt + 右键、中键或 Shift + 左键）。在焦点框体页面中设置。战斗中可用。"
L["Two new debuff filter modes: Raid Debuffs shows the common raid debuffs from anyone (armor, spell and physical damage taken, crit taken, attack power, attack and cast speed, healing taken, Judgements and Hunter's Mark), and Own and Raid Debuffs adds yours."] = "两种新的减益过滤模式：团队减益显示任何人施加的常见团队减益（护甲、受到的法术和物理伤害、受到的暴击、攻击强度、攻击和施法速度、受到的治疗、审判和猎人印记），自己的和团队减益则额外加入你施加的减益。"
L["Type Icon Position puts the icon of the player's highest dispellable debuff type on a point of the health bar, with its size and offsets in the cog. Only Dispellable by You now sits beside it and narrows the overlay, icon and border colors alike."] = "类型图标位置会将玩家最高可驱散减益类型的图标放在生命条的某个点上，其大小和偏移在齿轮中设置。“仅你可驱散”现在位于其旁边，并同样限制叠加、图标和边框颜色。"
L["The focus frame gets the aura Border Style, size and color settings, as player and target have."] = "焦点框体获得光环边框样式、大小和颜色设置，与玩家和目标相同。"
L["Player, target and focus show incoming heals past the health fill: yours and other players' in their own colors, from LibHealComm-4.0 (only healers running a HealComm addon are seen)."] = "玩家、目标和焦点在生命填充之后显示预计治疗：你的和其他玩家的分别使用各自颜色，数据来自 LibHealComm-4.0（只能看到运行 HealComm 插件的治疗者）。"
L["The debuff filters can now show or hide Sated, Exhaustion and the other Bloodlust lockout debuffs. They stay hidden by default."] = "减益过滤现在可以显示或隐藏心满意足、精疲力竭以及其他嗜血锁定减益。它们默认隐藏。"
L["Left, Right, Center and Extra Text, the Bottom Text Bar texts and Power Percent each have an Outline choice under Size: None, Outline, Thick Outline or Shadow, or the module default."] = "左侧、右侧、中央和额外文本、底部文本条的文本以及能量百分比，在大小下方都有轮廓选项：无、轮廓、粗轮廓或阴影，或模块默认。"
L["Anchor, growth, icons per row, duration and stack text, textured borders and dispel rings. Target and focus get Purgeable Buff Glow."] = "锚点、增长方向、每行图标数、持续时间和层数文本、纹理边框和驱散环。目标和焦点获得可净化增益发光。"
L["Every combat indicator style now shows, and highlighted portraits fit their shape instead of overflowing it."] = "所有战斗指示器样式现在都能显示，高亮的头像会贴合其形状而不再溢出。"
L["Player, target, focus and boss health bars show estimated damage shields with Retail's Absorb Style, Opacity, Color, Placement, Show Overshield and Show on Boss Frames"] = "玩家、目标、焦点和首领生命条使用正式服的吸收样式、不透明度、颜色、放置、显示过量护盾和在首领框体上显示来展示估算的伤害护盾"
L["Mana or Mana + Form Power, with a separate form bar"] = "法力值或法力值 + 形态能量，带独立的形态条"
L["Threat %, a pet power bar and the pet happiness icon"] = "仇恨 %、宠物能量条和宠物快乐度图标"
L["Pooled aura indicators on the health bar with Use Indicator Layout"] = "使用“使用指示器布局”时在生命条上显示的合并光环指示器"
L["Fill, full, gradient and sharp gradient overlays in the dispel color"] = "以驱散颜色显示的填充、全覆盖、渐变和锐利渐变叠加"
L["Under Classic WoW UI and Blizzard Style, the leader crown sits on the portrait's top corner, as on the original frames, instead of inside the health bar."] = "在经典 WoW UI 和暴雪样式下，队长皇冠位于头像的上角，与原版框体相同，而不是在生命条内。"
L["The party leader icon on unit frames shows on the leader only instead of on several party members."] = "单位框体上的小队队长图标只显示在队长身上，而不是多个小队成员身上。"
L["Set Focus and Clear Focus in the unit frame right-click menu work out of combat without the 'blocked from an action' popup; in combat they are hidden."] = "单位框体右键菜单中的设置焦点和清除焦点在脱离战斗时可用，不再弹出“被阻止执行动作”提示；战斗中它们被隐藏。"
L["Unit frame bars and portraits no longer get moved into scroll frames when !!!ClassicAPI is installed."] = "安装 !!!ClassicAPI 后，单位框体的条和头像不再被移到滚动框架中。"
L["Important Cast Glow is hidden for target and focus cast bars; the Wrath client cannot tell which spells are important."] = "目标和焦点施法条隐藏重要施法发光；巫妖王之怒客户端无法判断哪些法术是重要的。"
L["Channel cast bars show the spell's name instead of \"Channeling\"."] = "引导施法条显示法术名称，而不是 \"Channeling\"。"
L["Boss frames now update health, power and text while the boss is not your target or focus."] = "首领不是你的目标或焦点时，首领框体现在也会更新生命值、能量和文本。"
L["Visibility conditions (combat, group, and hiding without a target) now apply to the frames instead of stopping with an error, so the Visibility menu's boxes also tick right away."] = "可见性条件（战斗、队伍以及无目标时隐藏）现在会应用到框体上，而不是报错停止，因此可见性菜单的勾选框也会立即勾选。"
L["Classic WoW UI power bars now stay inside the frame art: the art's rim draws over the power bar as it does over the health bar."] = "经典 WoW UI 的能量条现在保持在框体美术之内：美术边缘会覆盖在能量条上，与生命条相同。"
L["Classic WoW UI now gives every unit frame the original green health bar instead of class colors. Returning to the EllesmereUI look restores your colors."] = "经典 WoW UI 现在让每个单位框体使用原版的绿色生命条，而不是职业颜色。切换回 EllesmereUI 外观会恢复你的颜色。"
L["Classic WoW UI power bars use the original game colors (deep blue mana, red rage, yellow energy) instead of the EllesmereUI palette. Other looks keep the palette."] = "经典 WoW UI 的能量条使用原版游戏颜色（深蓝法力、红色怒气、黄色能量），而不是 EllesmereUI 配色。其他外观保持该配色。"
L["Text outlines now apply to the live frames, not only the options preview."] = "文本轮廓现在应用到实际框体上，而不仅是选项预览。"
L["Unit frames no longer fail to load on setups whose mask textures come back empty (absorb bar error at login)."] = "在遮罩纹理返回为空的设置中，单位框体不再无法载入（登录时的吸收条错误）。"
L["Icons shown by spell ID now show the right icon or a question mark, never an empty square."] = "按法术 ID 显示的图标现在显示正确的图标或问号，而不会是空方块。"
L["The faction indicator no longer errors in mercenary mode, and Retail-only PvP styles use the Wrath PvP icon."] = "阵营指示器在雇佣兵模式下不再报错，仅限正式服的 PvP 样式会使用巫妖王之怒的 PvP 图标。"
L["Level text no longer errors with Font not set when frames are first created."] = "首次创建框体时，等级文本不再报错 Font not set。"
L["Like Retail 9.4, the Experience Bar section opens with XP Bar Style: EllesmereUI for the EUI bar, Luxthos for the EUI bar in the Luxthos WeakAura layout, or Blizz Default for Blizzard's own XP and reputation bars. It replaces Enable Experience Bar and the Apply Luxthos Layout button."] = "与正式服 9.4 相同，经验条区段开头为经验条样式：EllesmereUI 使用 EUI 经验条，Luxthos 使用 Luxthos WeakAura 布局的 EUI 经验条，暴雪默认使用暴雪自带的经验条和声望条。它取代了“启用经验条”和“应用 Luxthos 布局”按钮。"
L["Like Retail 9.4, any horizontal bar can show the classic gryphons at its left end, right end or both, from the End Caps menu at the end of LAYOUT. The cog sets their size and offsets, and Apply to All copies them to every bar. The live preview shows them too."] = "与正式服 9.4 相同，任何水平条都可以在其左端、右端或两端显示经典狮鹫，在布局末尾的端饰菜单中设置。齿轮可设置其大小和偏移，“应用于全部”会将其复制到所有条。实时预览也会显示它们。"
L["The XP bar gets Retail's Quest XP Overlay (completed quests in green, incomplete in gold), dividers with Smart Ticks, gradient fills, background and rested colors, and seven text positions showing values, completed quest XP, XP per hour, time to level and time played. Apply Luxthos Layout recreates the popular Luxthos XP bar WeakAura, with Show at Max Level, a spark and rested XP after quest XP."] = "经验条获得正式服的任务经验叠加（已完成任务为绿色，未完成为金色）、带智能刻度的分隔线、渐变填充、背景和休息颜色，以及七个文本位置，可显示数值、已完成任务经验、每小时经验、升级所需时间和游戏时间。“应用 Luxthos 布局”会重现流行的 Luxthos 经验条 WeakAura，带满级时显示、火花以及任务经验后的休息经验。"
L["Buttons holding an equipped item, such as a trinket, can show a border in its rarity color. Off by default."] = "放置已装备物品（例如饰品）的按钮可以显示其品质颜色的边框。默认关闭。"
L["Four extra bars, off by default, each with its own keybinds, Unlock Mode mover and the full Bar Display settings. Warriors, Druids, Rogues and Priests see which stance or form shares a bar's slots."] = "四个额外的条，默认关闭，每个都有自己的快捷键、解锁模式移动框和完整的条显示设置。战士、德鲁伊、潜行者和牧师可以看到哪个姿态或形态共享该条的槽位。"
L["Circle and Portrait draw round icons, Diamond, Hexagon and Shield crop the icon to the shape, and Square and Curved Square add a shaped outline. Set per bar, including pet and stance."] = "圆形和头像绘制圆形图标，菱形、六边形和护盾将图标裁剪为对应形状，方形和圆角方形添加形状轮廓。按条设置，包括宠物条和姿态条。"
L["Type /kb, hover a button and press a key to bind it, including modifiers, mouse buttons and the wheel. Right-click clears; Cancel or Esc undoes."] = "输入 /kb，悬停按钮并按下按键即可绑定，支持修饰键、鼠标按键和滚轮。右键点击清除；取消或 Esc 撤销。"
L["Per-bar text, borders, backgrounds, orientation and growth, the Retail button animations and visibility engine, and Bar 1 modifier paging."] = "按条设置的文本、边框、背景、方向和增长方向，正式服的按钮动画和可见性引擎，以及动作条 1 的修饰键翻页。"
L["Shift+1 shows as S1, Control+1 as C1, mouse buttons as M4 and the wheel as MwU/MwD"] = "Shift+1 显示为 S1，Control+1 显示为 C1，鼠标按键显示为 M4，滚轮显示为 MwU/MwD"
L["Shrink the bag bar to a single backpack button"] = "将背包栏缩小为单个行囊按钮"
L["Square micro menu and bag bar, flat XP and reputation bars and movable buffs and debuffs"] = "方形微菜单和背包栏、扁平的经验条和声望条，以及可移动的增益和减益"
L["Bar 1 paging arrows change the page without the \"blocked from an action only available to the Blizzard UI\" message."] = "动作条 1 的翻页箭头可切换页面，不再出现 \"blocked from an action only available to the Blizzard UI\" 消息。"
L["Changing stance no longer reveals a duplicate Blizzard stance and pet bar."] = "切换姿态时不再显示重复的暴雪姿态条和宠物条。"
L["Spells can be dropped on Bar 1 while the Blizzard bar art is hidden."] = "隐藏暴雪动作条美术时，仍可将法术拖放到动作条 1 上。"
L["Player Buffs keep growing downward as rows are added."] = "添加行时，玩家增益会继续向下增长。"
L["The XP and reputation bars no longer error on their first update."] = "经验条和声望条在首次更新时不再报错。"
L["Create Soulstone reminders, including custom spell reminders, only appear for Warlocks."] = "制造灵魂石提醒（包括自定义法术提醒）只对术士显示。"
L["A Holy-only reminder for your Seal of Wisdom, including when another seal is active."] = "仅神圣天赋的智慧圣印提醒，包括其他圣印生效时。"
L["One click casts your group buff, such as Fortitude, Gift of the Wild or Arcane Brilliance, at its highest rank on the first member missing it."] = "一键对第一个缺少团队增益的成员施放其最高等级的团队增益，例如真言术：韧、野性赐福或奥术光辉。"
L["Auras, presences, aspects, shields, weapon imbues, poisons, pets, Soulstone and Healthstone, plus flask, elixir and food with bag counts."] = "光环、灵界、守护、护盾、武器强化、毒药、宠物、灵魂石和治疗石，以及带背包数量的合剂、药剂和食物。"
L["Reminder sounds include SharedMedia sounds, even from packs that load later"] = "提醒音效包括 SharedMedia 声音，即使来自稍后载入的包"
L["World, normal and heroic dungeons and raids, or in combat, with Show Below timers"] = "野外、普通和英雄地下城与团队副本，或战斗中，带低于时显示计时"
L["Talent reminders for Wrath zones and your current instance"] = "针对巫妖王之怒区域和你当前副本的天赋提醒"
L["Your own aura ID reminders and a healer mana Ready Check Warning"] = "你自己的光环 ID 提醒和治疗者法力的就位确认警告"
L["Middle-click hides a reminder until the next loading screen"] = "中键点击可隐藏提醒，直到下一次载入画面"
L["Turning off Runeforging now hides the Death Knight rune reminder."] = "关闭符文熔铸现在会隐藏死亡骑士符文提醒。"
L["Adding zones to an older talent reminder no longer errors, and the new zones apply right away."] = "向旧的天赋提醒添加区域不再报错，新区域会立即生效。"
L["A coin in the bag header marks items as junk: click it, then click items. Grey and marked items go to a Junk category, and a Sell Junk button appears next to the coin at merchants. Its cog adds a coin badge on marked items."] = "背包标题栏中的硬币可将物品标记为垃圾：点击它，然后点击物品。灰色和已标记的物品会进入垃圾类别，在商人处硬币旁会出现出售垃圾按钮。其齿轮可在已标记物品上添加硬币徽章。"
L["Bag keybinds open and close the existing layout during combat. Layout refreshes wait until combat ends."] = "战斗中背包快捷键会打开和关闭现有布局。布局刷新会等到战斗结束。"
L["A sidebar with All Items, OneBag and MultiBag views, pinned and recent items, Retail categories for Wrath items and your own categories."] = "带所有物品、整合背包和多背包视图的侧栏，固定和最近物品，适用于巫妖王之怒物品的正式服类别，以及你自己的类别。"
L["OneBag merges stacks and sorts by bag type, MultiBag sorts each bag, with Sort to Bottom and Randomize."] = "整合背包会合并堆叠并按背包类型排序，多背包会对每个背包排序，支持从底部开始排列和随机。"
L["A cog beside the search opens the Bags options, or the Bank page at the bank"] = "搜索旁的齿轮会打开背包选项，在银行时则打开银行页面"
L["Each saved character in the Characters list has an x to delete its data"] = "角色列表中每个已保存的角色都有一个 x，可删除其数据"
L["Quality borders, quest marks, item level, BoE text, set names and dimmed junk"] = "品质边框、任务标记、物品等级、装备后绑定文本、套装名称和褪色的垃圾物品"
L["Group the bank by category, with a sidebar"] = "按类别分组银行，带侧栏"
L["With Enable Bags off, the default bag functions are no longer replaced, avoiding blocked action errors from tainted bag code."] = "关闭启用背包时，默认背包函数不再被替换，避免被污染的背包代码导致动作被阻止的错误。"
L["Opening the Characters list no longer errors."] = "打开角色列表不再报错。"
L["Gold sale ads with websites or cash prices, including 5000G=20 bucks and disguised W.W.W addresses, are filtered by default in your selected chat scopes."] = "带有网站或现金价格的金币出售广告（包括 5000G=20 bucks 和伪装的 W.W.W 地址）默认会在你所选的聊天范围中被过滤。"
L["Unsupported server channel notices such as NOT_IN_LFG no longer cause the native chat formatter to error."] = "NOT_IN_LFG 等不受支持的服务器频道通知不再导致原生聊天格式化程序报错。"
L["Optional spam filtering with a repeat window, sender matching and public, group or whisper controls."] = "可选的垃圾信息过滤，带重复时间窗口、发送者匹配以及公共、队伍或密语控制。"
L["Background, divider, input position, Retail border and tabs over the native dock, plus a sidebar with friends, guild, copy, channels and settings."] = "原生停靠栏上的背景、分隔线、输入框位置、正式服边框和标签页，以及带好友、公会、复制、频道和设置的侧栏。"
L["Retail timestamps, short channel names, class colored names, link tooltips, whisper sounds, saved chat history and Retail URL and copy windows."] = "正式服时间戳、简短频道名、职业着色名称、链接提示、密语音效、保存的聊天记录，以及正式服的网址和复制窗口。"
L["Show Hidden Messages lists the last 200 lines the spam filter hid this session, with time, reason, channel and sender. Clear Filter History is now Reset Repeat Memory."] = "显示被隐藏的消息会列出垃圾信息过滤在本次会话中隐藏的最近 200 行，包含时间、原因、频道和发送者。“清除过滤历史”现已改为“重置重复记忆”。"
L["The trade ad preset also hides LFW (looking for work) crafting ads."] = "交易广告预设也会隐藏 LFW（求工作）制造广告。"
L["Right-click the chat in Unlock Mode to open its Display settings"] = "在解锁模式中右键点击聊天框可打开其显示设置"
L["Restyled chat bubbles with per-channel toggles and hiding in instances"] = "重新设计的聊天气泡，带按频道开关和副本中隐藏"
L["The chat fades after a delay and comes back on mouseover"] = "聊天框在延迟后淡出，鼠标悬停时恢复"
L["Copy Chat copies the chat tab you are looking at instead of the last tab you right-clicked, which could show \"(No chat history)\"."] = "复制聊天会复制你正在查看的聊天标签页，而不是你上次右键点击的标签页（后者可能显示 \"(No chat history)\"）。"
L["Fixed a \"SetPoint(): is dependent on this\" error when styling some NPC chat bubbles."] = "修复了美化某些 NPC 聊天气泡时出现的 \"SetPoint(): is dependent on this\" 错误。"
L["The guild recruitment filter no longer hides raid ads that mention a guild, such as \"<Frost> LF 1 heal ICC25\"; only LF guild phrases count."] = "公会招募过滤不再隐藏提到公会的团队招募广告，例如 \"<Frost> LF 1 heal ICC25\"；只有寻找公会的短语才会计入。"
L["GM whispers and messages are never hidden by the spam filter."] = "GM 密语和消息永远不会被垃圾信息过滤隐藏。"
L["Spam filter keywords ignore case for accented letters too, so promoção also hides PROMOÇÃO."] = "垃圾信息过滤关键词对带重音的字母也不区分大小写，因此 promoção 也会隐藏 PROMOÇÃO。"
L["The trade ad and guild recruitment filters follow the Public Chat setting, and the spam filter does no work while every filter is off."] = "交易广告和公会招募过滤遵循公共聊天设置，并且所有过滤都关闭时垃圾信息过滤不进行任何处理。"
L["The sidebar shows on first load, and tabs and toggles update right away."] = "侧栏在首次载入时显示，标签页和开关会立即更新。"
L["The main chat keeps its Unlock Mode position instead of being reset by the dock."] = "主聊天框保持其解锁模式位置，而不再被停靠栏重置。"
L["A saved chat opacity of 0 resets once to the Retail default."] = "已保存的聊天不透明度为 0 时会一次性重置为正式服默认值。"
L["Square, rectangular, circle and textured circle maps, with border size, opacity, textured styles and custom, accent or class colors."] = "方形、矩形、圆形和带纹理圆形地图，可设置边框大小、不透明度、纹理样式以及自定义、强调色或职业颜色。"
L["Addon buttons collect into the Retail flyout with a grid, grow direction and Shift-drag Free Move."] = "插件按钮收纳到正式服的弹出菜单中，带网格、增长方向和 Shift 拖动的自由移动。"
L["A vanilla ring and zone banner with native zoom buttons"] = "经典圆环和区域横幅，带原生缩放按钮"
L["Clock and zone boxes in ten positions, plus coordinates, FPS and latency, and difficulty text"] = "可放在十个位置的时钟和区域框，以及坐标、FPS 和延迟、难度文本"
L["Guild and friends at a glance; left-click whispers, right-click invites"] = "一目了然的公会和好友；左键密语，右键邀请"
L["Menu actions open Blizzard windows through secure calls, avoiding blocked action errors."] = "菜单操作通过安全调用打开暴雪窗口，避免动作被阻止的错误。"
L["Pick Classic WoW UI for Damage Meters on the Style page: each window gets the classic tooltip border, a tooltip header band and vanilla header icons, and keeps every EllesmereUI meter feature."] = "在样式页面中为伤害统计选择经典 WoW UI：每个窗口获得经典鼠标提示边框、提示标题带和原版标题图标，并保留 EllesmereUI 统计的全部功能。"
L["A spell's breakdown tooltip shows its Spell ID, and each spell row in the detailed window ends with its ID."] = "法术的明细提示显示其法术 ID，详细窗口中每个法术行的末尾显示其 ID。"
L["Consumed shield absorbs count toward Healing Done and HPS when the caster can be identified, with an Absorbs Done view."] = "能识别施法者时，消耗的护盾吸收量计入造成治疗和 HPS，并提供造成吸收视图。"
L["Flat body, accent header, Atrocity bars and header icons for Settings, Segment, Meter Type and Reset, with up to five windows."] = "扁平主体、强调色标题、Atrocity 条，以及设置、分段、统计类型和重置的标题图标，最多五个窗口。"
L["Up to 15 spells and the top three targets on hover, death recaps with health at each hit, and a per-player focus view."] = "悬停时显示最多 15 个法术和前三名目标、带每次受击时生命值的死亡回顾，以及按玩家的焦点视图。"
L["SharedMedia bar textures load whether a profile stores them in Damage Meters or EllesmereUI format"] = "无论配置以伤害统计还是 EllesmereUI 格式保存，SharedMedia 条纹理都会载入"
L["An icon strip and bar window of your casts, including failed and interrupted ones"] = "显示你施法的图标条和条窗口，包括失败和被打断的施法"
L["A standalone combat timer with its own Unlock Mode element"] = "独立的战斗计时器，带自己的解锁模式元素"
L["Windows snap to each other; locked windows cannot move, resize or close"] = "窗口会相互吸附；锁定的窗口无法移动、调整大小或关闭"
L["Keybinds for Reset Data and Show / Hide Windows"] = "重置数据和显示 / 隐藏窗口的快捷键"
L["Specialization icons from talent data and paced group inspection"] = "根据天赋数据显示专精图标，并分批观察队伍成员"
L["Load an action menu only in your primary or secondary talent group, and let two menus share one keybind across specs."] = "仅在主天赋组或副天赋组中载入动作菜单，并允许两个菜单在不同专精间共用一个快捷键。"
L["Hold a key, point or scroll to choose, release to fire. Up to 16 palettes of 20 entries in ring, arc, fan or grid layouts."] = "按住按键，指向或滚动选择，松开即施放。最多 16 个面板，每个 20 个条目，可用环形、弧形、扇形或网格布局。"
L["An Action Menu entry fans out up to 8 actions from another palette, one level out from the ring."] = "动作菜单条目会从另一个面板展开最多 8 个动作，位于环形外一层。"
L["Accent, class or custom color for the selected entry, needle and nested highlight"] = "所选条目、指针和嵌套高亮的强调色、职业颜色或自定义颜色"
L["Set the gap between a nested menu and its entry, and the nested icon size"] = "设置嵌套菜单与其条目之间的间距，以及嵌套图标大小"
L["Reverse which way a wheel tick moves the selection"] = "反转滚轮每格移动选择的方向"
L["Assign Key captures the next key with modifiers and asks before rebinding"] = "分配按键会捕获下一个按键（含修饰键），并在重新绑定前询问"
L["Keep the menu open on release and fire with a Select key"] = "松开时保持菜单打开，并用选择键施放"
L["Red when out of range, blue when short of power, grey when unusable"] = "超出范围时为红色，能量不足时为蓝色，不可用时为灰色"
